    function chatTime(): any {
        var d: any = new Date();
        return ('0' + d.getHours()).slice(-2) + ':' + ('0' + d.getMinutes()).slice(-2);
    }

    /** แผงแชท 1 อันต่อเครื่องมือ — ต่อท้าย .aih-work เป็นคอลัมน์ที่ 3 */
    function buildChat(v?: any): any {
        var t: any = v.getAttribute('data-tool');
        var work: any = $('.aih-work', v);
        if (!work || !INFO[t] || $('.aih-chat', v)) {
            return;
        }
        CHATS[t] = [];
        chatNewSid(t);
        var card: any = document.createElement('div');
        card.className = 'aih-card aih-chat';
        card.innerHTML = '<div class="aih-chat-hd">ผู้ช่วย AI<span class="aih-chat-chip">AI พร้อมให้บริการ</span>'
                + '<span class="aih-chat-tools">'
                + '<button type="button" class="aih-chat-tb" data-chat="hist" title="ประวัติแชท" aria-label="ประวัติแชท"><i class="fa-solid fa-clock-rotate-left"></i></button>'
                + '<button type="button" class="aih-chat-tb" data-chat="new" title="เริ่มแชทใหม่" aria-label="เริ่มแชทใหม่"><i class="fa-regular fa-pen-to-square"></i></button>'
                + '<button type="button" class="aih-chat-tb" data-chat="dl" title="ดาวน์โหลดบทสนทนานี้" aria-label="ดาวน์โหลดบทสนทนา"><i class="fa-solid fa-download"></i></button>'
                + '</span></div>'
                + '<div class="aih-chat-dlm" hidden="hidden"><button type="button" data-chat="dl-md"><i class="fa-brands fa-markdown"></i> ไฟล์ Markdown (.md)</button>'
                + '<button type="button" data-chat="dl-pdf"><i class="fa-regular fa-file-pdf"></i> ไฟล์ PDF</button></div>'
                + '<div class="aih-chat-hero"><div class="aih-chat-hero-top"><img src="' + MASCOT + '" alt=""/>'
                + '<div><b>ผู้ช่วย' + esc(INFO[t].title) + '</b><small>ถามต่อ ขอคำแนะนำการใช้เครื่องมือ หรือสั่งให้ช่วยปรับตัวเลือก / เริ่มสร้างให้ได้เลยครับ (ผมจะถามยืนยันก่อนทำทุกครั้ง)</small></div></div>'
                + '<div class="aih-chat-sugs">' + chatTips(t).map(function(x?: any): any {
                    return '<button type="button" class="aih-chat-sug" data-chat-q="' + esc(x[1]) + '"><i class="' + x[0] + '"></i>' + esc(x[1]) + '</button>';
                }).join('') + '</div></div>'
                + '<div class="aih-chat-hist" hidden="hidden"></div>'
                + '<div class="aih-chat-body"></div>'
                + '<div class="aih-chat-ft"><div class="aih-chat-in">'
                /* data-allow-special: ยกเว้นตัวดักอักขระพิเศษ (input_guard.js) — ช่องคุยกับ AI ต้องพิมพ์/วางอะไรก็ได้ เหมือนหน้าแปลเอกสาร */
                + '<textarea class="aih-chat-ta" rows="1" maxlength="4000" data-allow-special="true" placeholder="พิมพ์ข้อความของคุณ..."></textarea>'
                + '<button type="button" class="aih-chat-send" data-act="chat-send" title="ส่ง"><i class="fa-solid fa-paper-plane"></i></button></div>'
                + '<div class="aih-chat-disc">AI อาจมีข้อผิดพลาด ควรตรวจสอบความถูกต้องอีกครั้ง</div></div>';
        work.appendChild(card);
        CHAT_READY[t] = chatResume(v);
        if (t === 'image') {
            /* ★ 06/11/2026 แผงแชทของสร้างรูปภาพปิดไว้ก่อน เปิดจากปุ่ม "แชทกับผู้ช่วย AI" — ปุ่ม X ปิดกลับ */
            $('.aih-chat-hd', card).insertAdjacentHTML('beforeend', '<button type="button" class="aih-im-chatx" data-im="chat-close" title="ปิด" aria-label="ปิดแชท"><i class="fa-solid fa-xmark"></i></button>');
        }
    }

    /** ข้อความจาก AI: escape ก่อนเสมอ แล้วค่อยแปลง ```โค้ด``` เป็นกล่องโค้ด และ **ตัวหนา** */
    function chatHtml(text?: any): any {
        var parts: any = String(text || '').split('```');
        return parts.map(function(seg?: any, i?: any): any {
            if (i % 2 === 1) {
                return '<pre>' + esc(seg.replace(/^[\w+#.-]*\n/, '').replace(/\n$/, '')) + '</pre>';
            }
            return esc(seg).replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>');
        }).join('');
    }

    function renderChat(v?: any, scroll?: any): any {
        var t: any = v.getAttribute('data-tool');
        var box: any = $('.aih-chat-body', v);
        if (!box) {
            return;
        }
        var av: any = '<div class="aih-msg-av"><img src="' + MASCOT + '" alt="ผู้ช่วย AI"/></div>';
        box.innerHTML = (CHATS[t] || []).map(function(m?: any, i?: any): any {
            if (m.note) {
                return '<div class="aih-chat-note"><span>' + esc(m.note) + '</span></div>';
            }
            if (m.typing) {
                return '<div class="aih-msg">' + av + '<div><div class="aih-bub" style="padding:0;"><div class="aih-typing"><span></span><span></span><span></span></div></div></div></div>';
            }
            var me: any = m.from === 'user';
            return '<div class="aih-msg' + (me ? ' me' : '') + (m.error ? ' err' : '') + '">'
                    + (me ? '<div class="aih-msg-av"><i class="fa-regular fa-user"></i></div>' : av)
                    + '<div><div class="aih-bub' + (m.kind === 'output' ? ' aih-bub-out' : '') + '">' + (me ? esc(m.text) : chatHtml(m.text)) + '</div>'
                    + (!me && m.actions && m.actions.length ? chatActionsHtml(m, i) : '')
                    + '<div class="aih-msg-meta"><span>' + esc(m.time) + '</span>'
                    + (!me && !m.error ? '<button type="button" class="aih-msg-copy" data-act="chat-copy" data-i="' + i + '"><i class="fa-regular fa-copy"></i> คัดลอก</button>' : '')
                    + '</div></div></div>';
        }).join('');
        if (scroll !== false) {
            box.scrollTop = box.scrollHeight;
        }
    }

    function chatNote(v?: any, text?: any): any {
        var t: any = v.getAttribute('data-tool');
        if (CHATS[t] && CHATS[t].length) {
            CHATS[t].push({note: text});
            renderChat(v);
        }
    }

    /**
     * ค่าในฟอร์มด้านซ้ายเป็นข้อความที่คนอ่าน: "ชื่อช่องบนจอ: ค่าที่เลือก [ตัวเลือก: ...]" (ไฟล์แนบส่งแค่ชื่อ)
     * ★ ไม่ส่งชื่อพารามิเตอร์ (genre / lang / instrumental) — รอบแรกผู้ช่วยพูดชื่อเหล่านั้นกับผู้ใช้ตรง ๆ
     *   และเสนอค่าที่ไม่มีในตัวเลือก (เช่น "pop-acoustic") ; ส่งชื่อช่องภาษาไทย + ตัวเลือกที่มีจริงแทน
     */
    function formText(v?: any): any {
        var txt: any = function(el?: any): any { return (el.textContent || '').replace(/\s+/g, ' ').trim(); };
        var lines: any[] = [];
        $$(CHAT_FIELDS, v).forEach(function(el?: any): any {
            var field: any = closest(el, '.aih-field');
            var lbl: any = field && $('.aih-lbl', field);
            var label: any = lbl ? txt(lbl) : chatFieldId(el);
            var value: any, options: any[] = [];
            if (el.classList.contains('aih-chips') || el.classList.contains('aih-skins')) {
                value = $$('.on', el).map(txt).join(', ');
                options = Array.prototype.map.call(el.children, txt);
            } else if (el.tagName === 'SELECT') {
                value = el.selectedIndex >= 0 ? txt(el.options[el.selectedIndex]) : '';
                options = Array.prototype.map.call(el.options, txt);
            } else if (el.type === 'checkbox') {
                label = txt(closest(el, 'label') || el);
                value = el.checked ? 'เลือก' : 'ไม่เลือก';
            } else {
                value = String(el.value || '').trim();
            }
            lines.push(label + ': ' + (value || '(ว่าง)') + (options.length ? ' [ตัวเลือกที่มี: ' + options.join(' | ') + ']' : ''));
        });
        var files: any = filesOf(v).map(function(f?: any): any { return f.name; });
        if (files.length) {
            lines.push('ไฟล์แนบ: ' + files.join(', '));
        }
        return lines.join('\n');
    }

    function chatSend(v?: any, text?: any): any {
        var t: any = v.getAttribute('data-tool');
        var ta: any = $('.aih-chat-ta', v);
        var msg: any = String(text != null ? text : (ta ? ta.value : '')).trim();
        if (!msg || CHAT_BUSY[t]) {
            return;
        }
        if (ta && text == null) {
            ta.value = '';
            ta.style.height = 'auto';
        }
        var history: any = CHATS[t].filter(function(m?: any): any { return m.from && !m.error; }).slice(-12)
                .map(function(m?: any): any { return {from: m.from, text: m.text, kind: m.kind || ''}; });
        CHATS[t].push({from: 'user', text: msg, time: chatTime()});
        CHATS[t].push({typing: true});
        renderChat(v);
        CHAT_BUSY[t] = true;
        setChatBusy(v, true);

        var form: any = new FormData();
        form.append('tool', t);
        form.append('message', msg);
        form.append('history', JSON.stringify(history));
        form.append('form', formText(v));
        form.append('formSpec', JSON.stringify(chatFormSpec(v)));
        form.append('sessionId', CHAT_SID[t]);
        var chatModel: any = $('[data-chat-model]', v);
        if (chatModel) {
            form.append('model', chatModel.value);
        }
        if (LAST[t]) {
            form.append('result', JSON.stringify(LAST[t], function(k?: any, val?: any): any { return k === 'xml' ? undefined : val; }));
            if (LAST[t].docId) {
                form.append('docId', LAST[t].docId);
            }
            /* ★ 18/11/2026 ไม่ส่ง historyId แล้ว — แชทเป็นบทสนทนาต่อเนื่องของเครื่องมือ ไม่ผูกกับรายการผลลัพธ์ใดรายการหนึ่ง */
        }
        call('chat', form).then(function(res?: any): any {
            CHATS[t] = CHATS[t].filter(function(m?: any): any { return !m.typing; });
            var rr: any = res.result || {}, acts: any = rr.actions || [];
            CHATS[t].push({from: 'ai', text: rr.reply || '', time: chatTime(), actions: acts, astate: acts.length ? 'pending' : ''});
            if (rr.saveError) {
                CHATS[t].push({note: 'บันทึกประวัติแชทไม่สำเร็จ: ' + rr.saveError});
            }
        }).catch(function(err?: any): any {
            CHATS[t] = CHATS[t].filter(function(m?: any): any { return !m.typing; });
            /* ขึ้นในแชท ไม่ใช่ popup — เห็นว่าคำถามไหนไม่สำเร็จ และพิมพ์ถามใหม่ได้ทันที */
            CHATS[t].push({from: 'ai', text: 'ขออภัยครับ ' + (err.message || String(err)), time: chatTime(), error: true});
        }).then(function(): any {
            CHAT_BUSY[t] = false;
            setChatBusy(v, false);
            renderChat(v);
        });
    }

    function setChatBusy(v?: any, busy?: any): any {
        var chip: any = $('.aih-chat-chip', v);
        if (chip) {
            chip.classList.toggle('busy', busy);
            chip.textContent = busy ? 'AI กำลังคิด...' : 'AI พร้อมให้บริการ';
        }
        var btn: any = $('.aih-chat-send', v);
        if (btn) {
            btn.disabled = busy;
        }
    }

    /* ★ ปุ่มผู้ช่วย AI ลอย (ai_menu.xhtml) อยู่มุมขวาล่างพอดีกับช่องพิมพ์ของแชท และผู้ใช้ลากย้ายได้
       — วัดว่าทับกันจริงไหม แล้วเว้นขอบขวาของช่องพิมพ์ให้พ้นปุ่ม (ลากปุ่มไปที่อื่นแล้วช่องพิมพ์กลับเต็มความกว้าง) */
    function avoidFab(): any {
        var ft: any = current && $('.aih-chat-ft', current);
        if (!ft) {
            return;
        }
        ft.style.paddingRight = '';
        /* วัดที่ตัวปุ่ม ไม่ใช่ .ai-fab-root — กล่องนอกรวมเมนูที่กางออกด้วย กว้าง/สูงกว่าตัวปุ่มมาก */
        var fab: any = document.querySelector('.ai-fab-btn') || document.querySelector('.ai-fab-root');
        if (!fab || !fab.offsetWidth) {
            return;
        }
        var a: any = ft.getBoundingClientRect(), b: any = fab.getBoundingClientRect();
        var overlap: any = b.left < a.right && b.right > a.left && b.top < a.bottom && b.bottom > a.top;
        if (overlap && b.left > a.left + 160) {
            ft.style.paddingRight = Math.round(a.right - b.left + 8) + 'px';
        }
    }

    // ═══ เพลง ═══════════════════════════════════════════════════════════

    var SONG: any = null;
    var GENRE_TH: any = {pop: 'ป๊อป', ballad: 'บัลลาด', acoustic: 'อะคูสติก', rock: 'ร็อก', edm: 'EDM', lukthung: 'ลูกทุ่ง',
        jazz: 'แจ๊ส', corporate: 'Corporate', kids: 'เพลงเด็ก'};
    var MOOD_TH: any = {happy: 'สดใส', inspiring: 'ให้กำลังใจ', calm: 'ผ่อนคลาย', romantic: 'โรแมนติก', energetic: 'คึกคัก',
        fun: 'สนุกสนาน', sad: 'เศร้า'};
    var INSTRUMENT_TH: any = {piano: 'เปียโน', epiano: 'อิเล็กทริกเปียโน', guitar: 'กีตาร์', synth: 'ซินธิไซเซอร์', flute: 'ฟลุต',
        strings: 'เครื่องสาย', marimba: 'มาริมบา', bell: 'ระฆัง', pluck: 'ฮาร์ป', organ: 'ออร์แกน'};

    /** เนื้อเพลงพร้อมคอร์ดเป็นข้อความธรรมดา — วางใน LINE / Word แล้วอ่านได้ทันที */
    function lyricSheet(r?: any): any {
        var lines: any = [r.title || '', [GENRE_TH[r.genre] || r.genre, r.key, (r.bpm || '') + ' BPM'].filter(Boolean).join(' · '), ''];
        (r.sections || []).forEach(function(s?: any): any {
            lines.push('[' + s.label + ']');
            lines.push((s.chords || []).join(' | '));
            (s.lyrics || []).forEach(function(l?: any): any { lines.push(l); });
            lines.push('');
        });
        return lines.join('\n').trim();
    }

    function slideSub(s?: any): any {
        return s.subtitle || (s.bullets || []).slice(0, 3).join(' · ');
    }

    // ═══ คลิป: ถามสถานะงานเรนเดอร์จนเสร็จ ═════════════════════════════

    /* ★ 18/10/2026 — บัญชีเรนเดอร์ Luma ได้ทีละ 1 คลิป บริการจึงทำทีละฉาก (ฉากละ ~1–3 นาที) งาน 10 ฉากอาจถึง 30 นาที
       ถามทุก 10 วิ ไม่เกิน 45 นาที ; งานยังเดินต่อที่บริการแม้ปิดหน้านี้ แต่หน้าจอจะไม่รู้ jobId อีก */
    /** คลิปแต่ละฉาก — คลิปในประวัติใช้ไฟล์ในประวัติ (S3) ; คลิปใหม่ใช้ /files (หมดอายุใน 72 ชม.) */
    function clipsHtml(list?: any): any {
        return (list || []).map(function(c?: any): any {
            var url: any = function(dl?: any): any {
                return c.historyFileId ? API + '/history/' + encodeURIComponent(c.historyFileId) + (dl ? '?download=1' : '')
                        : fileUrl(c.fileId, dl);
            };
            return '<figure><video controls="controls" preload="metadata" src="' + url(false) + '"></video>'
                    + '<figcaption>ฉาก ' + esc(c.scene) + ' · <a href="' + url(true) + '">ดาวน์โหลด</a></figcaption></figure>';
        }).join('');
    }

    function pollVideo(v?: any, jobId?: any, n?: any): any {
        if (n > 270) {
            setVideoStatus(v, 'ยังเรนเดอร์ไม่เสร็จหลัง 45 นาที กรุณาลองสร้างใหม่ภายหลัง', true);
            return;
        }
        setTimeout(function(): any {
            var form: any = new FormData();
            form.append('jobId', jobId);
            call('video-status', form).then(function(res?: any): any {
                var s: any = res.result || {};
                var clips: any = $('#aihClips', v);
                if (clips) {
                    clips.innerHTML = clipsHtml(s.clips);
                }
                if (s.status === 'completed') {
                    setVideoStatus(v, 'เรนเดอร์เสร็จครบ ' + s.total + ' ฉาก', true);
                } else if (s.status === 'failed') {
                    setVideoStatus(v, s.message || 'สร้างคลิปไม่สำเร็จ', true);
                } else {
                    setVideoStatus(v, s.message || 'กำลังเรนเดอร์…');
                    pollVideo(v, jobId, n + 1);
                }
            }).catch(function(err?: any): any {
                setVideoStatus(v, err.message, true);
            });
        }, 10000);
    }

    function setVideoStatus(v?: any, text?: any, done?: any): any {
        var box: any = $('#aihVideoStatus', v);
        if (box) {
            box.innerHTML = (done ? '<i class="fa-solid fa-circle-info"></i>' : '<span class="aih-orb"></span>') + '<span>' + esc(text) + '</span>';
        }
    }

    // ═══ ถามต่อจากเอกสาร ════════════════════════════════════════════════

    function ask(box?: any): any {
        var input: any = $('input', box);
        var q: any = input.value.trim();
        if (!q) {
            input.focus();
            return;
        }
        var docId: any = box.getAttribute('data-doc-id');
        // ★ 24/10/2026 ผลที่อยู่ในประวัติ: docId ว่าง (เปิดจากประวัติ) หรือหมดเวลาแล้ว → ให้บริการเปิดไฟล์ต้นฉบับจาก S3 ใหม่ (reopen)
        var hid: any = box.getAttribute('data-history-id') || '';
        if (!docId && !hid) {
            mockMsg('ถามต่อจากผลลัพธ์ตัวอย่าง');
            return;
        }
        var list: any = box.previousElementSibling && box.previousElementSibling.classList.contains('aih-qa-list')
                ? box.previousElementSibling : box.parentNode;
        var item: any = document.createElement('div');
        item.className = 'aih-qa';
        item.innerHTML = '<div class="q">' + esc(q) + '</div><div class="aih-status"><span class="aih-orb"></span><span>กำลังหาคำตอบจากเอกสาร…</span></div>';
        list.appendChild(item);
        reveal(item);
        input.value = '';
        var btn: any = $('button', box);
        btn.disabled = true;
        var askModel: any = $('[data-model-select]', closest(box, '.aih-view'));
        var send: any = function(id?: any): any {
            var form: any = new FormData();
            form.append('docId', id);
            if (askModel) {
                form.append('model', askModel.value);
            }
            form.append('question', q);
            if (hid) {
                form.append('historyId', hid);     /* เก็บคำถามต่อไว้กับรายการในประวัติ */
            }
            return call('doc-ask', form);
        };
        var reopenAndSend: any = function(): any {
            var s: any = $('.aih-status span:last-child', item);
            if (s) {
                s.textContent = 'กำลังเปิดเอกสารต้นฉบับจากประวัติ…';
            }
            return histReopen(hid).then(function(id?: any): any {
                box.setAttribute('data-doc-id', id);
                if (s) {
                    s.textContent = 'กำลังหาคำตอบจากเอกสาร…';
                }
                return send(id);
            });
        };
        (docId ? send(docId).catch(function(err?: any): any {
            if (!hid || !/หมดเวลา|ไม่พบ/.test(err.message || '')) {
                throw err;
            }
            return reopenAndSend();
        }) : reopenAndSend()).then(function(res?: any): any {
            var r: any = res.result || {};
            item.innerHTML = qaHtml(r.question || q, r.answer || 'ไม่พบคำตอบในเอกสาร', r.citations);
        }).catch(function(err?: any): any {
            item.innerHTML = '<div class="q">' + esc(q) + '</div><div class="aih-note warn"><i class="fa-solid fa-triangle-exclamation"></i><span>'
                    + esc(err.message) + '</span></div>';
        }).then(function(): any {
            btn.disabled = false;
            reveal(item);
        });
    }

    /** เลื่อนกล่องผลลัพธ์ให้เห็นคำถาม-คำตอบล่าสุด (คำตอบยาวดันช่องถามลงไปนอกจอ) */
    function reveal(el?: any): any {
        if (el && el.scrollIntoView) {
            el.scrollIntoView({block: 'nearest', behavior: 'smooth'});
        }
    }

    // ═══ โค้ด: แท็บไฟล์ + ไฮไลต์สีแบบง่าย ════════════════════════════════

    var CODE_FILES: any = [
        {name: 'InstallmentCalculator.java', content: [
            'package com.example.finance;', '',
            'import java.math.BigDecimal;', 'import java.math.MathContext;', 'import java.math.RoundingMode;', '',
            '/**', ' * คำนวณค่างวดผ่อนชำระรายเดือน (เงินงวดเท่ากันทุกเดือน)', ' */',
            'public final class InstallmentCalculator {', '',
            '    private static final BigDecimal MONTHS_X_100 = BigDecimal.valueOf(1200);', '',
            '    private InstallmentCalculator() { }', '',
            '    /**', '     * @param principal  ยอดจัด (บาท)', '     * @param annualRate ดอกเบี้ยต่อปี (%) เช่น 6.5',
            '     * @param months     จำนวนงวด', '     * @return ค่างวดต่อเดือน ปัดทศนิยม 2 ตำแหน่ง', '     */',
            '    public static BigDecimal monthly(BigDecimal principal, BigDecimal annualRate, int months) {',
            '        if (months <= 0) {', '            throw new IllegalArgumentException("months must be greater than 0");', '        }',
            '        BigDecimal r = annualRate.divide(MONTHS_X_100, MathContext.DECIMAL64);',
            '        if (r.signum() == 0) {',
            '            return principal.divide(BigDecimal.valueOf(months), 2, RoundingMode.HALF_UP);', '        }',
            '        BigDecimal factor = BigDecimal.ONE.add(r).pow(months, MathContext.DECIMAL64);',
            '        return principal.multiply(r).multiply(factor)',
            '                .divide(factor.subtract(BigDecimal.ONE), 2, RoundingMode.HALF_UP);', '    }', '}'
        ].join('\n')},
        {name: 'InstallmentCalculatorTest.java', content: [
            'package com.example.finance;', '',
            'import static org.junit.jupiter.api.Assertions.assertEquals;',
            'import static org.junit.jupiter.api.Assertions.assertThrows;', '',
            'import java.math.BigDecimal;', 'import org.junit.jupiter.api.Test;', '',
            'class InstallmentCalculatorTest {', '',
            '    @Test', '    void standardLoan() {',
            '        BigDecimal pay = InstallmentCalculator.monthly(',
            '                new BigDecimal("1000000"), new BigDecimal("6.5"), 60);',
            '        assertEquals(new BigDecimal("19566.15"), pay);', '    }', '',
            '    @Test', '    void zeroInterestSplitsEvenly() {',
            '        assertEquals(new BigDecimal("10000.00"),',
            '                InstallmentCalculator.monthly(new BigDecimal("120000"), BigDecimal.ZERO, 12));', '    }', '',
            '    @Test', '    void rejectsNonPositiveMonths() {',
            '        assertThrows(IllegalArgumentException.class,',
            '                () -> InstallmentCalculator.monthly(BigDecimal.TEN, BigDecimal.ONE, 0));', '    }', '}'
        ].join('\n')}
    ];
    var curCode: any = 0;

    var KW: any = /^(package|import|public|private|protected|static|final|class|interface|enum|extends|implements|void|int|long|double|float|boolean|char|byte|short|return|if|else|for|while|do|switch|case|break|continue|throw|throws|try|catch|finally|new|null|true|false|this|super|var|let|const|function|async|await|def|from|as|in|is|not|and|or|None|True|False|elif|lambda|yield|with|pass|SELECT|FROM|WHERE|JOIN|LEFT|RIGHT|INNER|ON|GROUP|BY|ORDER|HAVING|INSERT|INTO|VALUES|UPDATE|SET|DELETE|CREATE|TABLE|AS|AND|OR|NOT|NULL|LIMIT)$/;
    /* comment ของแต่ละภาษา — # เฉพาะ Python/shell, -- เฉพาะ SQL (ไม่งั้น i-- ของ Java/JS กลายเป็น comment ทั้งบรรทัด) */
    function tokenizer(fileName?: any): any {
        var ext: any = String(fileName || '').split('.').pop()!.toLowerCase();
        var comment: any = '\\/\\*[\\s\\S]*?\\*\\/|\\/\\/[^\\n]*';
        if (ext === 'py' || ext === 'sh' || ext === 'yml' || ext === 'yaml' || ext === 'properties' || ext === 'ps1') {
            comment = '#[^\\n]*';
        } else if (ext === 'sql') {
            comment = '--[^\\n]*|\\/\\*[\\s\\S]*?\\*\\/';
        }
        return new RegExp('(' + comment + ')|("(?:\\\\.|[^"\\\\\\n])*"|\'(?:\\\\.|[^\'\\\\\\n])*\'|`(?:\\\\.|[^`\\\\])*`)'
                + '|(@\\w+)|\\b([A-Za-z_]\\w*)\\b|\\b(\\d+(?:\\.\\d+)?)\\b', 'g');
    }

    function highlight(src?: any, fileName?: any): any {
        var out: any = '', last: any = 0, m: any;
        var TOKEN: any = tokenizer(fileName);
        while ((m = TOKEN.exec(src)) !== null) {
            if (m[0] === '') {
                TOKEN.lastIndex++;
                continue;
            }
            out += esc(src.slice(last, m.index));
            var cls: any = m[1] ? 'c' : m[2] ? 's' : m[3] ? 'a'
                    : m[4] ? (KW.test(m[4]) ? 'k' : (/^[A-Z][a-z]/.test(m[4]) ? 't' : '')) : 'n';
            out += cls ? '<span class="' + cls + '">' + esc(m[0]) + '</span>' : esc(m[0]);
            last = TOKEN.lastIndex;
        }
        return out + esc(src.slice(last));
    }

    function showCode(v?: any, i?: any): any {
        var f: any = CODE_FILES[i];
        var src: any = $('.aih-src', v);
        if (!f || !src) {
            return;
        }
        curCode = i;
        src.innerHTML = highlight(f.content || '', f.name);
        var n: any = String(f.content || '').split('\n').length, nums: any = [];
        for (var k: any = 1; k <= n; k++) {
            nums.push(k);
        }
        $('.aih-gutter', v).textContent = nums.join('\n');
        $$('.aih-code-tab', v).forEach(function(t?: any): any {
            t.classList.toggle('on', t.getAttribute('data-file') === String(i));
        });
    }

    // ═══ ศึกษาวิธีทำงาน: ติ๊กขั้นตอน ═════════════════════════════════════

    function syncSteps(v?: any): any {
        var steps: any = $$('.aih-step', v);
        var flow: any = $$('.aih-flow-step', v);
        var done: any = 0;
        steps.forEach(function(s?: any, i?: any): any {
            var on: any = $('input', s).checked;
            s.classList.toggle('done', on);
            if (flow[i]) {
                flow[i].classList.toggle('done', on);
            }
            if (on) {
                done++;
            }
        });
        var bar: any = $('.aih-progress .bar i', v);
        var txt: any = $('.aih-progress-txt', v);
        if (bar) {
            bar.style.width = (steps.length ? Math.round(done * 100 / steps.length) : 0) + '%';
        }
        if (txt) {
            txt.textContent = done + ' / ' + steps.length;
        }
    }

    // ═══ งานล่าสุดของฉัน (localStorage — ของผู้ใช้คนนี้บนเบราว์เซอร์นี้เท่านั้น) ═══

    var RECENT_KEY: any = 'aihub.recent.v1';

    function loadRecent(): any {
        try {
            var a: any = JSON.parse(window.localStorage.getItem(RECENT_KEY) || '[]');
            return Array.isArray(a) ? a : [];
        } catch (e: any) {
            return [];
        }
    }

    function saveRecent(a?: any): any {
        try { window.localStorage.setItem(RECENT_KEY, JSON.stringify(a.slice(0, 100))); } catch (e: any) {}
    }

    function remember(t?: any, r?: any): any {
        if (!INFO[t]) {
            return;
        }
        var label: any = '';
        if (t === 'doc-analyze') {
            label = ((r.documents || [])[0] || {}).name || r.documentType;
        } else if (t === 'image') {
            label = r.prompt;
        } else if (t === 'code') {
            label = ((r.files || [])[0] || {}).name;
        } else if (t === 'library-ask') {
            label = r.question;
        } else {
            label = r.title;
        }
        var a: any = loadRecent();
        a.unshift({t: t, label: String(label || '').slice(0, 120), at: Date.now()});
        saveRecent(a);
    }

    function ago(ms?: any): any {
        var m: any = Math.max(0, Math.round((Date.now() - ms) / 60000));
        if (m < 1) { return 'เมื่อสักครู่'; }
        if (m < 60) { return m + ' นาที'; }
        var h: any = Math.round(m / 60);
        if (h < 24) { return h + ' ชม.'; }
        var d: any = Math.round(h / 24);
        return d === 1 ? 'เมื่อวาน' : d + ' วัน';
    }

    function renderHome(): any {
        var list: any = document.getElementById('aihRecent');
        if (!list) {
            return;
        }
        var a: any = loadRecent().filter(function(x?: any): any { return INFO[x.t]; });
        list.innerHTML = a.length ? a.slice(0, 6).map(function(x?: any): any {
            var i: any = INFO[x.t];
            return '<li data-g="' + G_ATTR[i.g] + '"><a href="' + esc(toolLink(x.t)) + '"><span class="ic"><i class="' + i.icon + '"></i></span>'
                    + '<div><b>' + esc(i.title) + '</b><small>' + esc(x.label || '-') + '</small></div></a><time>' + ago(x.at) + '</time></li>';
        }).join('') : '<li class="aih-empty-list">ยังไม่มีงาน — เลือกเครื่องมือด้านซ้ายเพื่อเริ่มต้น</li>';

        var now: any = new Date();
        var month: any = a.filter(function(x?: any): any {
            var d: any = new Date(x.at);
            return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth();
        });
        var by: any = {};
        month.forEach(function(x?: any): any { by[INFO[x.t].g] = (by[INFO[x.t].g] || 0) + 1; });
        var max: any = usageMax(by);
        $$('#aihUsage .aih-usage-row').forEach(function(rowEl?: any): any {
            var n: any = by[rowEl.getAttribute('data-group')] || 0;
            $('b', rowEl).textContent = n;
            $('.aih-usage-bar i', rowEl).style.setProperty('--w', Math.round(n * 100 / max) + '%');
        });
        var total: any = document.getElementById('aihUsageTotal');
        if (total) {
            total.textContent = month.length + ' งาน';
        }
        var hero: any = document.getElementById('aihMonthCount');
        if (hero) {
            hero.textContent = month.length;
        }
    }

    // ═══ ★ 18/10/2026 — การใช้งานจริงของผู้ใช้ที่เข้าระบบ (ฐานข้อมูล aitran.aihub_usage ผ่าน /aihub/usage) ═══
    /* war ใส่ตัวตน (ผู้ใช้ / สาขา ggwbranch ที่เลือกตอนเข้าระบบ) ให้เอง — หน้าเว็บส่งอะไรไปก็ไม่มีผล
       โหลดไม่ได้ / บริการยังไม่เปิดบันทึก = คงข้อมูลจากเบราว์เซอร์นี้ (renderHome) ไว้ตามเดิม */

    var MONTH_TH: any = ['ม.ค.', 'ก.พ.', 'มี.ค.', 'เม.ย.', 'พ.ค.', 'มิ.ย.', 'ก.ค.', 'ส.ค.', 'ก.ย.', 'ต.ค.', 'พ.ย.', 'ธ.ค.'];
    var EXTRA_INFO: any = {
        'chat': {g: 'assistant', title: 'แชทกับผู้ช่วย AI', icon: 'fa-solid fa-comments'},
        'doc-ask': {g: 'document', title: 'ถามต่อจากเอกสาร', icon: 'fa-solid fa-circle-question'}
    };

    /** ค่าสูงสุดของแถบจำนวนงานแยกกลุ่ม — ★ 25/10/2026 นับทุกกลุ่ม (เดิมไม่นับ Sales แถบจึงเกิน 100% ได้) */
    function usageMax(by?: any): any {
        return Math.max.apply(null, [1].concat(Object.keys(by).map(function(k?: any): any { return Number(by[k]) || 0; })));
    }

    function fmtTok(n?: any): any {
        n = Number(n) || 0;
        if (n >= 1e6) { return (n / 1e6).toFixed(1).replace(/\.0$/, '') + 'M'; }
        if (n >= 1e4) { return Math.round(n / 1e3) + 'K'; }
        if (n >= 1e3) { return (n / 1e3).toFixed(1).replace(/\.0$/, '') + 'K'; }
        return String(n);
    }

    function setText(id?: any, text?: any): any {
        var el: any = document.getElementById(id);
        if (el) {
            el.textContent = text;
        }
    }

    function tokenCardMessage(msg?: any): any {
        var box: any = document.getElementById('aihTokenModels');
        if (box) {
            box.innerHTML = '<div class="aih-empty-list">' + esc(msg) + '</div>';
        }
    }

    function loadUsage(): any {
        if (!document.getElementById('aihTokenCard')) {
            return;
        }
        env.fetch(API + '/usage', {credentials: 'same-origin', cache: 'no-store', headers: {'Accept': 'application/json'}})
                .then(readJson)
                .then(function(j?: any): any {
                    if (j.ok && j.enabled) {
                        renderUsage(j);
                    } else {
                        tokenCardMessage(j.ok ? 'บริการ AI HUB ยังไม่ได้เปิดบันทึกการใช้งาน' : (j.error || 'โหลดข้อมูลการใช้งานไม่ได้'));
                    }
                }, function(): any {
                    tokenCardMessage('ติดต่อบริการ AI HUB ไม่ได้');
                });
    }

    function renderUsage(j?: any): any {
        var me: any = j.me || {};
        // งานล่าสุด — ของผู้ใช้คนนี้จากฐานข้อมูล (ทุกเครื่อง ทุกเบราว์เซอร์)
        var list: any = document.getElementById('aihRecent');
        /* ★ 12/11/2026 "งานล่าสุดของฉัน" ไม่แสดงรายการแชทกับผู้ช่วย AI (tool chat) — แชทดูได้จากปุ่มประวัติแชทในแต่ละเครื่องมือ */
        var rec: any = (me.recent || []).filter(function(x?: any): any { return x.tool !== 'chat' && (INFO[x.tool] || EXTRA_INFO[x.tool]); });
        if (list) {
            list.innerHTML = rec.length ? rec.slice(0, 6).map(function(x?: any): any {
                var i: any = INFO[x.tool] || EXTRA_INFO[x.tool];
                var href: any = INFO[x.tool] ? toolLink(x.tool) : '#';
                return '<li data-g="' + (G_ATTR[i.g] || '') + '"><a href="' + esc(href) + '"><span class="ic"><i class="' + i.icon + '"></i></span>'
                        + '<div><b>' + esc(i.title) + '</b><small>' + esc(x.label || '-') + '</small>'
                        + '<span class="meta">' + (x.model ? logoHtml(x.logo, 'aih-logo-xs') : '') + esc(x.model || '')
                        + (x.tokens ? ' · ' + fmtTok(x.tokens) + ' token' : '')
                        + (x.images ? ' · ' + x.images + ' ภาพ' : '') + '</span></div></a>'
                        + '<time>' + ago(Date.parse(x.at)) + '</time></li>';
            }).join('') : '<li class="aih-empty-list">ยังไม่มีงาน — เลือกเครื่องมือด้านซ้ายเพื่อเริ่มต้น</li>';
        }
        var clear: any = $('[data-act="clear-recent"]');
        if (clear) {
            clear.style.display = 'none';   // ประวัติในฐานข้อมูลลบจากหน้านี้ไม่ได้
        }
        // จำนวนงานแยกกลุ่ม
        var by: any = me.byGroup || {};
        var max: any = usageMax(by);
        $$('#aihUsage .aih-usage-row').forEach(function(rowEl?: any): any {
            var n: any = by[rowEl.getAttribute('data-group')] || 0;
            $('b', rowEl).textContent = n;
            $('.aih-usage-bar i', rowEl).style.setProperty('--w', Math.round(n * 100 / max) + '%');
        });
        setText('aihUsageTotal', (me.runs || 0) + ' งาน');
        setText('aihMonthCount', me.runs || 0);
        setText('aihMonthTokens', fmtTok(me.totalTokens));

        // การ์ด token
        var m: any = String(j.month || '').split('-');
        setText('aihTokenMonth', m.length === 2 ? MONTH_TH[Number(m[1]) - 1] + ' ' + (Number(m[0]) + 543) : '—');
        /* ★ 1.0.71 บอกว่ายอดนี้เป็นของใคร — ล็อกอินคนละบัญชีต้องเห็นชื่อและตัวเลขของตัวเองเท่านั้น */
        var who: any = j.who || {};
        setText('aihTokenWho', who.name || who.username ? 'ของ ' + (who.name || who.username) + (who.username && who.name ? ' (' + who.username + ')' : '') : '');
        setText('aihTokenTotal', fmtNum(me.totalTokens));
        setText('aihTokenIn', fmtNum(me.inputTokens));
        setText('aihTokenOut', fmtNum(me.outputTokens));
        var media: any = document.getElementById('aihTokenMedia');
        if (media) {
            media.innerHTML = (me.images ? '<i class="fa-solid fa-image"></i> ภาพ <b>' + fmtNum(me.images) + '</b>' : '')
                    + (me.videoSeconds ? ' <i class="fa-solid fa-film"></i> วิดีโอ <b>' + fmtNum(me.videoSeconds) + '</b> วิ' : '')
                    + (me.audioSeconds ? ' <i class="fa-solid fa-microphone-lines"></i> ถอดเสียง <b>' + fmtNum(Math.round(me.audioSeconds / 60)) + '</b> นาที' : '');
        }
        var models: any = me.byModel || [];
        var value: any = function(x?: any): any {
            return x.kind === 'image' ? (x.images || 0) : x.kind === 'video' ? (x.videoSeconds || 0) : (x.inputTokens || 0) + (x.outputTokens || 0);
        };
        var maxOf: any = {};
        models.forEach(function(x?: any): any { maxOf[x.kind] = Math.max(maxOf[x.kind] || 1, value(x)); });
        var box: any = document.getElementById('aihTokenModels');
        if (box) {
            box.innerHTML = models.length ? models.map(function(x?: any): any {
                var v: any = value(x);
                var unit: any = x.kind === 'image' ? ' ภาพ' : x.kind === 'video' ? ' วิ' : ' token';
                return '<div class="aih-token-row" data-vendor="' + esc(x.vendor || '') + '" title="' + esc(x.model) + ' · ' + x.runs + ' งาน">'
                        + '<span class="nm">' + logoHtml(x.logo, 'aih-logo-xs') + esc(x.label) + '<small>' + x.runs + ' งาน</small></span>'
                        + '<span class="vl">' + fmtNum(v) + unit + '</span>'
                        + '<span class="bar"><i style="--w:' + Math.max(3, Math.round(v * 100 / maxOf[x.kind])) + '%"></i></span></div>';
            }).join('') : '<div class="aih-empty-list">ยังไม่มีการใช้งานเดือนนี้</div>';
        }
        var b: any = j.branch || {};
        var branchBox: any = document.getElementById('aihTokenBranch');
        if (branchBox) {
            branchBox.innerHTML = (b.code || b.name) && b.runs != null
                    ? '<i class="fa-solid fa-building"></i><span>ทั้งสาขา <b>' + esc(b.name || b.code) + '</b> เดือนนี้ <b>'
                        + fmtNum(b.totalTokens) + '</b> token · ' + fmtNum(b.runs) + ' งาน · ' + fmtNum(b.users) + ' คน</span>'
                    : '';
        }
    }

    // ═══ ภาพประกอบของตัวอย่าง: ฉากบ้านวาดด้วย SVG ═══════════════════════

    var SCENE: any = '<svg viewBox="0 0 320 180" preserveAspectRatio="xMidYMax slice" aria-hidden="true">'
            + '<circle cx="232" cy="62" r="24" fill="rgba(255,255,255,.55)"/>'
            + '<path d="M0 122 Q70 92 150 116 T320 104 V180 H0Z" fill="rgba(17,24,39,.16)"/>'
            + '<rect x="96" y="104" width="92" height="50" fill="rgba(17,24,39,.42)"/>'
            + '<path d="M86 107 L142 74 L198 107Z" fill="rgba(17,24,39,.55)"/>'
            + '<rect x="108" y="118" width="18" height="14" rx="2" fill="rgba(255,236,170,.9)"/>'
            + '<rect x="158" y="118" width="18" height="14" rx="2" fill="rgba(255,236,170,.9)"/>'
            + '<rect x="133" y="128" width="16" height="26" rx="2" fill="rgba(17,24,39,.5)"/>'
            + '<circle cx="62" cy="128" r="17" fill="rgba(17,24,39,.4)"/><rect x="60" y="136" width="4" height="20" fill="rgba(17,24,39,.5)"/>'
            + '<circle cx="234" cy="132" r="13" fill="rgba(17,24,39,.38)"/><rect x="232" y="138" width="4" height="16" fill="rgba(17,24,39,.5)"/>'
            + '<path d="M0 150 Q80 138 160 152 T320 146 V180 H0Z" fill="rgba(17,24,39,.48)"/>'
            + '</svg>';

    // ═══ ★ 06/11/2026 — สร้างไฟล์ GIF (Content Creation) ════════════════════════════════
    /* ทำงานในเบราว์เซอร์ล้วน: เฟรมมาจาก (1) ภาพที่อัปโหลด หรือ (2) ให้ AI สร้างชุดภาพต่อเนื่อง (ใช้เส้น image เดิม —
       ภาพแรกสร้างจากคำบรรยาย ภาพถัดไปสร้างตามภาพแรกด้วย style-guide เพื่อให้ตัวละคร/สไตล์เหมือนกัน) แล้วเข้ารหัส GIF89a เอง
       (median-cut 256 สี/เฟรม + LZW) จึงไม่ต้องมีบริการหลังบ้านเพิ่ม และไม่มีไฟล์ใดถูกส่งออกนอกระบบนอกจากตอนให้ AI สร้างเฟรม */

    var GF: any = {frames: [], url: '', busy: false};
    var GF_MAX: any = 20;

    function gfVal(v?: any, f?: any): any {
        var g: any = $('[data-gf-field="' + f + '"]', v), on: any = g ? g.querySelector('.aih-chip.on') : null;
        return on ? on.getAttribute('data-value') : '';
    }

    /** median-cut: พิกเซล RGBA → {pal: Uint8Array(768), idx: Uint8Array(n)} */
    function gfQuantize(px?: any, n?: any): any {
        var hist: any = new Int32Array(32768), i: any, key: any;
        for (i = 0; i < n; i++) {
            key = ((px[i * 4] >> 3) << 10) | ((px[i * 4 + 1] >> 3) << 5) | (px[i * 4 + 2] >> 3);
            hist[key]++;
        }
        var all: any[] = [];
        for (key = 0; key < 32768; key++) {
            if (hist[key]) { all.push(key); }
        }
        function chOf(k?: any, ch?: any): any { return ch === 0 ? k >> 10 : ch === 1 ? (k >> 5) & 31 : k & 31; }
        function range(box?: any): any {
            var lo: any = [31, 31, 31], hi: any = [0, 0, 0], k: any, ch: any, c: any;
            for (k = 0; k < box.length; k++) {
                for (ch = 0; ch < 3; ch++) {
                    c = chOf(box[k], ch);
                    if (c < lo[ch]) { lo[ch] = c; }
                    if (c > hi[ch]) { hi[ch] = c; }
                }
            }
            var best: any = 0;
            for (ch = 1; ch < 3; ch++) {
                if (hi[ch] - lo[ch] > hi[best] - lo[best]) { best = ch; }
            }
            return {ch: best, span: hi[best] - lo[best]};
        }
        var boxes: any = [all];
        while (boxes.length < 256) {
            var pick: any = -1, pickScore: any = 0, pr: any = null, b: any, r: any, score: any;
            for (b = 0; b < boxes.length; b++) {
                if (boxes[b].length < 2) { continue; }
                r = range(boxes[b]);
                score = r.span * Math.sqrt(boxes[b].length);
                if (score > pickScore) { pick = b; pickScore = score; pr = r; }
            }
            if (pick < 0) { break; }
            var box: any = boxes[pick], tot: any = 0, half: any = 0, cut: any = 1, k2: any;
            box.sort(function(a?: any, c?: any): any { return chOf(a, pr.ch) - chOf(c, pr.ch); });
            for (k2 = 0; k2 < box.length; k2++) { tot += hist[box[k2]]; }
            for (k2 = 0; k2 < box.length - 1; k2++) {
                half += hist[box[k2]];
                cut = k2 + 1;
                if (half * 2 >= tot) { break; }
            }
            boxes.splice(pick, 1, box.slice(0, cut), box.slice(cut));
        }
        var pal: any = new Uint8Array(768), map: any = new Uint8Array(32768), bi: any;
        for (bi = 0; bi < boxes.length; bi++) {
            var sr: any = 0, sg: any = 0, sb: any = 0, sw: any = 0, kk: any, kv: any, wt: any;
            for (kk = 0; kk < boxes[bi].length; kk++) {
                kv = boxes[bi][kk];
                wt = hist[kv];
                sr += (kv >> 10) * wt; sg += ((kv >> 5) & 31) * wt; sb += (kv & 31) * wt; sw += wt;
                map[kv] = bi;
            }
            var cr: any = Math.round(sr / sw), cg: any = Math.round(sg / sw), cb: any = Math.round(sb / sw);
            pal[bi * 3] = (cr << 3) | (cr >> 2);
            pal[bi * 3 + 1] = (cg << 3) | (cg >> 2);
            pal[bi * 3 + 2] = (cb << 3) | (cb >> 2);
        }
        var idx: any = new Uint8Array(n);
        for (i = 0; i < n; i++) {
            idx[i] = map[((px[i * 4] >> 3) << 10) | ((px[i * 4 + 1] >> 3) << 5) | (px[i * 4 + 2] >> 3)];
        }
        return {pal: pal, idx: idx};
    }

    /** LZW ของ GIF (รหัสเริ่มต้น 8 บิต) → push เข้า out เป็น sub-block */
    function gfLzw(idx?: any, out?: any): any {
        var CLEAR: any = 256, EOI: any = 257, next: any = 258, size: any = 9, bits: any = 0, nb: any = 0, buf: any = [], dict: any = new Int32Array(4096 * 256).fill(-1);
        function put(code?: any): any {
            bits |= code << nb;
            nb += size;
            while (nb >= 8) { buf.push(bits & 255); bits >>= 8; nb -= 8; }
        }
        put(CLEAR);
        var prefix: any = idx[0], i: any, k: any, key: any;
        for (i = 1; i < idx.length; i++) {
            k = idx[i];
            key = prefix * 256 + k;
            if (dict[key] >= 0) {
                prefix = dict[key];
                continue;
            }
            put(prefix);
            if (next === 4096) {
                put(CLEAR);
                next = 258;
                size = 9;
                dict.fill(-1);
            } else {
                if (next >= (1 << size)) { size++; }
                dict[key] = next++;
            }
            prefix = k;
        }
        put(prefix);
        put(EOI);
        if (nb > 0) { buf.push(bits & 255); }
        out.push(8);
        for (i = 0; i < buf.length; i += 255) {
            var len: any = Math.min(255, buf.length - i);
            out.push(len);
            for (k = 0; k < len; k++) { out.push(buf[i + k]); }
        }
        out.push(0);
    }

    function gfFrameBytes(out?: any, q?: any, w?: any, h?: any, delayMs?: any): any {
        var cs: any = Math.max(2, Math.round(delayMs / 10)), i: any;
        out.push(0x21, 0xF9, 4, 0x04, cs & 255, cs >> 8, 0, 0);
        out.push(0x2C, 0, 0, 0, 0, w & 255, w >> 8, h & 255, h >> 8, 0x87);
        for (i = 0; i < 768; i++) { out.push(q.pal[i]); }
        gfLzw(q.idx, out);
    }

    function gfHeader(w?: any, h?: any, loop?: any): any {
        var out: any = [0x47, 0x49, 0x46, 0x38, 0x39, 0x61, w & 255, w >> 8, h & 255, h >> 8, 0x70, 0, 0];
        if (loop >= 0) {
            out.push(0x21, 0xFF, 0x0B);
            'NETSCAPE2.0'.split('').forEach(function(c?: any): any { out.push(c.charCodeAt(0)); });
            out.push(3, 1, loop & 255, loop >> 8, 0);
        }
        return out;
    }

    function gfLoadImage(file?: any): any {
        return new Promise(function(resolve?: any, reject?: any): any {
            var url: any = URL.createObjectURL(file), img: any = new Image();
            img.onload = function(): any { URL.revokeObjectURL(url); resolve(img); };
            img.onerror = function(): any { URL.revokeObjectURL(url); reject(new Error('เปิดไฟล์ภาพ ' + (file.name || '') + ' ไม่ได้')); };
            img.src = url;
        });
    }

    /** วาดภาพแบบ "เต็มกรอบ ตัดส่วนเกิน" ; zoom > 1 = ขยายเข้าหากึ่งกลาง */
    function gfDraw(g?: any, img?: any, w?: any, h?: any, zoom?: any): any {
        var s: any = Math.max(w / img.naturalWidth, h / img.naturalHeight) * (zoom || 1);
        var dw: any = img.naturalWidth * s, dh: any = img.naturalHeight * s;
        g.fillStyle = '#fff';
        g.fillRect(0, 0, w, h);
        g.drawImage(img, (w - dw) / 2, (h - dh) / 2, dw, dh);
    }

    function gfBuild(v?: any): any {
        if (GF.busy) { return; }
        if (GF.frames.length < 2) {
            popup('ต้องมีอย่างน้อย 2 ภาพเป็นเฟรม — อัปโหลดภาพเพิ่ม หรือให้ AI สร้างเฟรมให้', 'warning');
            return;
        }
        var w: any = Math.round((parseInt(gfVal(v, 'width'), 10) || 480) / 2) * 2, hold: any = parseInt(gfVal(v, 'delay'), 10) || 500;
        var trans: any = gfVal(v, 'trans') || 'cut', loopV: any = gfVal(v, 'loop') === 'once' ? -1 : 0;
        var pingpong: any = !!($('[data-gf-field="pingpong"]', v) || {}).checked;
        var out: any = $('.aih-output', v), btn: any = $('[data-gf="build"]', v);
        GF.busy = true;
        btn.disabled = true;
        var stop: any = startLoading(out, ['กำลังเตรียมภาพ…', 'กำลังเข้ารหัสเป็น GIF…', 'กำลังรวมไฟล์…']);
        var txt: any = $('.aih-loading-txt', out);
        Promise.all(GF.frames.map(function(f?: any): any { return gfLoadImage(f.file); })).then(function(imgs?: any): any {
            var first: any = imgs[0], h: any = Math.max(16, Math.round(w * first.naturalHeight / first.naturalWidth / 2) * 2);
            if (h > w * 2) { h = w * 2; }
            var cv: any = document.createElement('canvas'), g: any;
            cv.width = w; cv.height = h;
            g = cv.getContext('2d', {willReadFrequently: true});
            var plan: any = [], i: any, k: any;           /* แผนเฟรม: {a, b, t, zoom, ms} */
            for (i = 0; i < imgs.length; i++) {
                if (trans === 'zoom') {
                    for (k = 0; k < 8; k++) { plan.push({a: i, zoom: 1 + 0.16 * k / 7, ms: Math.max(40, hold / 8)}); }
                } else {
                    plan.push({a: i, zoom: 1, ms: hold});
                }
                if (trans === 'fade' && i < imgs.length - 1) {
                    for (k = 1; k <= 4; k++) { plan.push({a: i, b: i + 1, t: k / 5, zoom: 1, ms: 70}); }
                }
            }
            if (trans === 'fade' && imgs.length > 2 && !pingpong) {      /* วนกลับภาพแรกแบบนุ่ม */
                for (k = 1; k <= 4; k++) { plan.push({a: imgs.length - 1, b: 0, t: k / 5, zoom: 1, ms: 70}); }
            }
            if (pingpong) {
                for (i = plan.length - 2; i >= 1; i--) { plan.push(plan[i]); }
            }
            if (plan.length > 160) {
                throw new Error('เฟรมรวม ' + plan.length + ' เฟรม มากเกินไป — ลดจำนวนภาพ ปิด ping-pong หรือเลือกเปลี่ยนภาพแบบ "ตัดฉาก"');
            }
            var bytes: any = gfHeader(w, h, loopV), n: any = w * h, done: any = 0;
            return new Promise(function(resolve?: any, reject?: any): any {
                (function step(): any {
                    try {
                        if (done >= plan.length) {
                            bytes.push(0x3B);
                            resolve({bytes: bytes, w: w, h: h, frames: plan.length});
                            return;
                        }
                        var p: any = plan[done];
                        gfDraw(g, imgs[p.a], w, h, p.zoom);
                        var d: any = g.getImageData(0, 0, w, h);
                        if (p.b != null) {
                            var cv2: any = document.createElement('canvas');
                            cv2.width = w; cv2.height = h;
                            var g2: any = cv2.getContext('2d', {willReadFrequently: true});
                            gfDraw(g2, imgs[p.b], w, h, 1);
                            var d2: any = g2.getImageData(0, 0, w, h).data, a: any = d.data, j: any;
                            for (j = 0; j < a.length; j++) { a[j] = a[j] + (d2[j] - a[j]) * p.t; }
                        }
                        gfFrameBytes(bytes, gfQuantize(d.data, n), w, h, p.ms);
                        done++;
                        txt.textContent = 'กำลังเข้ารหัสเป็น GIF… ' + done + '/' + plan.length + ' เฟรม';
                        setTimeout(step, 0);
                    } catch (e: any) {
                        reject(e);
                    }
                })();
            });
        }).then(function(res?: any): any {
            stop();
            var blob: any = new Blob([new Uint8Array(res.bytes)], {type: 'image/gif'});
            if (GF.url) { URL.revokeObjectURL(GF.url); }
            GF.url = URL.createObjectURL(blob);
            gfShow(v, blob, res);
            remember('gif', {title: 'GIF ' + res.frames + ' เฟรม · ' + res.w + '×' + res.h});
            LAST.gif = {title: 'GIF ' + res.frames + ' เฟรม', prompt: (($('[data-gf-field="prompt"]', v) || {}).value || ''), plan: gfPlanText(v),
                frames: res.frames, width: res.w, height: res.h, sizeKB: Math.round(blob.size / 1024), source: v.getAttribute('data-gf-src')};
        }).catch(function(err?: any): any {
            stop();
            popup((err && err.message) || String(err), 'error', 'สร้าง GIF ไม่สำเร็จ');
        }).then(function(): any {
            GF.busy = false;
            gfSync(v);
        });
    }

    function gfShow(v?: any, blob?: any, res?: any): any {
        var body: any = $('.aih-out-body', v), size: any = fmtSize(blob.size);
        var name: any = 'animation-' + new Date().toISOString().slice(0, 10) + '.gif';
        body.innerHTML = '<div class="aih-gif-view"><div class="aih-gif-stage"><img src="' + GF.url + '" alt="ตัวอย่าง GIF"/></div>'
                + '<div class="aih-gif-info"><span><i class="fa-solid fa-film"></i> ' + res.frames + ' เฟรม</span>'
                + '<span><i class="fa-solid fa-expand"></i> ' + res.w + '×' + res.h + ' px</span>'
                + '<span><i class="fa-solid fa-weight-hanging"></i> ' + size + '</span></div>'
                + (blob.size > 8 * 1048576 ? '<div class="aih-note warn"><i class="fa-solid fa-triangle-exclamation"></i><span>ไฟล์ใหญ่กว่า 8 MB — โซเชียลและแชทส่วนใหญ่ไม่รับ ลองลดความกว้าง ลดจำนวนภาพ หรือใช้ "ตัดฉาก"</span></div>' : '')
                + '</div>';
        $('.aih-out-meta', v).textContent = res.frames + ' เฟรม · ' + res.w + '×' + res.h + ' · ' + size;
        $('.aih-out-acts', v).innerHTML = '<a class="aih-btn aih-btn-sm" data-gf="download" href="' + GF.url + '" download="' + name
                + '"><i class="fa-solid fa-download"></i> ดาวน์โหลด .gif</a>';
    }

    function gfSync(v?: any): any {
        var n: any = GF.frames.length, list: any = $('.aih-gif-frames', v);
        list.innerHTML = GF.frames.map(function(f?: any, i?: any): any {
            return '<div class="aih-gif-fr" data-gf-i="' + i + '"><img src="' + f.url + '" alt="เฟรม ' + (i + 1) + '"/><b>' + (i + 1) + '</b>'
                    + '<span><button type="button" data-gf="left" title="เลื่อนไปก่อน"' + (i ? '' : ' disabled="disabled"') + '><i class="fa-solid fa-chevron-left"></i></button>'
                    + '<button type="button" data-gf="right" title="เลื่อนไปหลัง"' + (i < n - 1 ? '' : ' disabled="disabled"') + '><i class="fa-solid fa-chevron-right"></i></button>'
                    + '<button type="button" data-gf="del" title="เอาออก"><i class="fa-solid fa-xmark"></i></button></span></div>';
        }).join('');
        $('.aih-gif-count', v).textContent = n ? n + ' / ' + GF_MAX + ' เฟรม' : 'ยังไม่มีเฟรม';
        $('.aih-gif-empty', v).hidden = n > 0;
        $('[data-gf="build"]', v).disabled = GF.busy;       /* ไม่ปิดปุ่มเมื่อเฟรมไม่พอ — กดแล้วต้องมีข้อความบอก ไม่ใช่เงียบ */
        var need: any = $('.aih-gif-need', v);
        need.hidden = n >= 2;
        need.textContent = n ? 'ต้องมีอย่างน้อย 2 เฟรมถึงจะสร้าง GIF ได้ (ตอนนี้มี ' + n + ')' : 'เพิ่มภาพหรือให้ AI สร้างเฟรมอย่างน้อย 2 เฟรมก่อน';
        $('[data-gf="ai"]', v).disabled = GF.busy;
        $('[data-gf="clear"]', v).hidden = !n;
    }

    function gfAdd(v?: any, files?: any): any {
        var added: any = 0;
        Array.prototype.forEach.call(files || [], function(f?: any): any {
            if (!/^image\//.test(f.type || '') && !/\.(jpe?g|png|webp|gif|bmp)$/i.test(f.name || '')) { return; }
            if (GF.frames.length >= GF_MAX) { return; }
            GF.frames.push({file: f, url: URL.createObjectURL(f)});
            added++;
        });
        if (files && files.length && added < files.length) {
            popup('รับได้เฉพาะไฟล์ภาพ และไม่เกิน ' + GF_MAX + ' เฟรม — เพิ่มได้ ' + added + ' จาก ' + files.length + ' ไฟล์', 'warning');
        }
        gfSync(v);
    }

    /** ให้ AI (เส้น chat) วางท่าทางทีละเฟรม → ["เฟรม 1 ...", ...] ; โยน error ถ้าอ่านผลไม่ได้ */
    function gfPlan(v?: any, n?: any, prompt?: any): any {
        var f: any = new FormData();
        f.append('tool', 'gif');
        f.append('message', 'วางแผนแอนิเมชัน GIF ' + n + ' เฟรมของ: "' + prompt + '"\n'
                + 'ตอบเป็น JSON array ของสตริงภาษาไทยจำนวน ' + n + ' ข้อเท่านั้น ห้ามมีข้อความอื่นหรือ markdown ครอบ ข้อละ 1 เฟรม '
                + 'บรรยายท่าทาง/ตำแหน่งของตัวแบบในเฟรมนั้นสั้น ๆ ให้ค่อย ๆ ขยับต่อเนื่อง และเฟรมสุดท้ายใกล้เคียงเฟรมแรกเพื่อให้วนลูปลื่น '
                + 'ตัวแบบ ฉาก และมุมกล้องต้องเหมือนเดิมทุกเฟรม');
        f.append('history', '[]');
        f.append('form', '');
        var cm: any = $('[data-chat-model]', v);
        if (cm) { f.append('model', cm.value); }
        return call('chat', f).then(function(res?: any): any {
            var txt: any = String((res.result || {}).reply || ''), a: any = txt.indexOf('['), b: any = txt.lastIndexOf(']'), arr: any;
            try { arr = JSON.parse(txt.slice(a, b + 1)); } catch (e: any) { arr = null; }
            if (!arr || !arr.length) { throw new Error('AI วางแผนไม่เป็นรูปแบบที่อ่านได้'); }
            arr = arr.map(function(x?: any): any { return String(x).replace(/^\s*(เฟรม(ที่)?\s*)?\d+\s*[:.)\-–]\s*/, '').trim(); }).filter(Boolean);
            while (arr.length < n) { arr.push(arr[arr.length - 1]); }
            return arr.slice(0, n);
        });
    }

    function gfPlanText(v?: any): any {
        return (($('[data-gf-field="plan"]', v) || {}).value || '').split('\n').map(function(x?: any): any { return x.trim(); }).filter(Boolean);
    }

    function gfPlanClick(v?: any): any {
        if (GF.busy) { return; }
        var prompt: any = (($('[data-gf-field="prompt"]', v) || {}).value || '').trim();
        if (!prompt) {
            popup('กรุณาบรรยายสิ่งที่จะให้ขยับก่อน', 'warning');
            return;
        }
        var n: any = parseInt(gfVal(v, 'aicount'), 10) || 4, btn: any = $('[data-gf="plan"]', v), old: any = btn.innerHTML;
        GF.busy = true;
        btn.disabled = true;
        btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> AI กำลังวางแผน…';
        gfPlan(v, n, prompt).then(function(arr?: any): any {
            $('[data-gf-field="plan"]', v).value = arr.join('\n');
        }).catch(function(err?: any): any {
            popup((err && err.message) || String(err), 'error', 'ให้ AI วางแผนไม่สำเร็จ');
        }).then(function(): any {
            GF.busy = false;
            btn.disabled = false;
            btn.innerHTML = old;
            gfSync(v);
        });
    }

    function gfAi(v?: any): any {
        if (GF.busy) { return; }
        var prompt: any = (($('[data-gf-field="prompt"]', v) || {}).value || '').trim();
        if (!prompt) {
            popup('กรุณาบรรยายสิ่งที่จะให้ขยับก่อน เช่น "แมวส้มโบกมือทักทาย"', 'warning');
            return;
        }
        var n: any = parseInt(gfVal(v, 'aicount'), 10) || 4, ratio: any = gfVal(v, 'ratio') || '1:1', style: any = gfVal(v, 'style') || 'cartoon';
        var out: any = $('.aih-output', v);
        GF.busy = true;
        gfSync(v);
        var stop: any = startLoading(out, ['AI กำลังวางแผนท่าทางทีละเฟรม…', 'AI กำลังวาดเฟรมแรก…', 'กำลังวาดเฟรมที่เหลือให้ต่อเนื่องกัน…', 'กำลังรวบรวมภาพ…']);
        var plan: any = gfPlanText(v);
        (plan.length >= n ? Promise.resolve(plan) : gfPlan(v, n, prompt).then(function(arr?: any): any {
            $('[data-gf-field="plan"]', v).value = arr.join('\n');
            return arr;
        }, function(): any { return []; })).then(function(steps?: any): any {
            var f: any = new FormData();
            f.append('mode', 'generate');
            f.append('prompt', prompt + (steps[0] ? ' — เฟรมแรก: ' + steps[0] : '') + ' — เฟรมแรกของแอนิเมชันสั้น พื้นหลังเรียบ ตัวแบบอยู่กลางภาพ');
            f.append('ratio', ratio);
            f.append('style', style);
            f.append('count', '1');
            f.append('negative', 'ตัวอักษร, ลายน้ำ');
            var ms: any = $('[data-model-select]', v), tm: any = $('[data-text-model-select]', v);
            if (ms && ms.value) { f.append('model', ms.value); }
            if (tm && tm.value) { f.append('textModel', tm.value); }
            return call('image', f).then(function(res?: any): any { return {res: res, steps: steps}; });
        }).then(function(x?: any): any {
            var res: any = x.res, steps: any = x.steps;
            var im: any = ((res.result || {}).images || [])[0];
            if (!im) { throw new Error('AI ไม่ส่งภาพกลับมา (อาจถูกตัวกรองเนื้อหาปฏิเสธ) ลองปรับคำบรรยาย'); }
            return imFetchFile(outUrl(im), 'frame-1').then(function(base?: any): any {
                var jobs: any[] = [];
                for (var k: any = 2; k <= n; k++) {
                    jobs.push(imRefCall(base, prompt + (steps[k - 1] ? ' — ท่าทางในเฟรมนี้: ' + steps[k - 1] : '') + ' — นี่คือเฟรมที่ ' + k + ' จาก ' + n + ' ของแอนิเมชันสั้นเรื่องเดียวกัน ใช้ตัวแบบ ฉาก มุมกล้อง สัดส่วน และสไตล์เดียวกับภาพอ้างอิงทุกประการ'
                            + ' ขยับท่าทางหรือตำแหน่งต่อจากเฟรมก่อนหน้าเพียงเล็กน้อยเพื่อให้เห็นเป็นการเคลื่อนไหวต่อเนื่อง', ratio));
                }
                return Promise.all(jobs).then(function(all?: any): any { return {base: base, all: all}; });
            });
        }).then(function(x?: any): any {
            return Promise.all([x.base].concat(x.all.map(function(r?: any): any {
                var im: any = r.ok ? (((r.res || {}).result || {}).images || [])[0] : null;
                return im ? imFetchFile(outUrl(im), 'frame').catch(function(): any { return null; }) : null;
            })));
        }).then(function(files?: any): any {
            stop();
            var ok: any = files.filter(Boolean);
            GF.frames.forEach(function(fr?: any): any { URL.revokeObjectURL(fr.url); });
            GF.frames = [];
            ok.forEach(function(file?: any, i?: any): any {
                var named: any = new File([file], 'frame-' + (i + 1) + (/png/.test(file.type) ? '.png' : '.jpg'), {type: file.type});
                GF.frames.push({file: named, url: URL.createObjectURL(named)});
            });
            if (ok.length < n) {
                popup('AI สร้างเฟรมได้ ' + ok.length + ' จาก ' + n + ' เฟรม (บางเฟรมไม่สำเร็จ) — กดสร้าง GIF ได้เลย หรือสร้างใหม่อีกครั้ง', 'warning');
            }
        }).catch(function(err?: any): any {
            stop();
            popup((err && err.message) || String(err), 'error', 'ให้ AI สร้างเฟรมไม่สำเร็จ');
        }).then(function(): any {
            GF.busy = false;
            gfSync(v);
        });
    }

    function gfInit(v?: any): any {
        var sample: any = $('.aih-sample', v);
        if (sample) { sample.remove(); }
        v.addEventListener('click', function(e?: any): any {
            var chip: any = closest(e.target, '[data-gf-field] .aih-chip');
            if (chip || closest(e.target, '[data-gf]')) {
                e.stopPropagation();        /* ตัวจัดการคลิกกลางบน root สลับ .on ของ chip ซ้ำอีกรอบ */
            }
            if (chip) {
                $$('.aih-chip', chip.parentNode).forEach(function(c?: any): any { c.classList.toggle('on', c === chip); });
                if (chip.parentNode.getAttribute('data-gf-field') === 'src') {
                    v.setAttribute('data-gf-src', chip.getAttribute('data-value'));
                }
                return;
            }
            var el: any = closest(e.target, '[data-gf]');
            if (!el) { return; }
            var cmd: any = el.getAttribute('data-gf'), fr: any = closest(el, '[data-gf-i]'), i: any = fr ? parseInt(fr.getAttribute('data-gf-i'), 10) : -1;
            if (cmd === 'build') {
                gfBuild(v);
            } else if (cmd === 'ai') {
                gfAi(v);
            } else if (cmd === 'plan') {
                gfPlanClick(v);
            } else if (cmd === 'pick') {
                $('.aih-gif-file', v).click();
            } else if (cmd === 'clear') {
                GF.frames.forEach(function(f?: any): any { URL.revokeObjectURL(f.url); });
                GF.frames = [];
                gfSync(v);
            } else if (cmd === 'del' && i >= 0) {
                URL.revokeObjectURL(GF.frames[i].url);
                GF.frames.splice(i, 1);
                gfSync(v);
            } else if ((cmd === 'left' || cmd === 'right') && i >= 0) {
                var j: any = cmd === 'left' ? i - 1 : i + 1;
                if (j >= 0 && j < GF.frames.length) {
                    var tmp: any = GF.frames[i];
                    GF.frames[i] = GF.frames[j];
                    GF.frames[j] = tmp;
                    gfSync(v);
                }
            }
        });
        $('.aih-gif-file', v).addEventListener('change', function(e?: any): any {
            gfAdd(v, e.target.files);
            e.target.value = '';
        });
        var drop: any = $('.aih-gif-drop', v);
        ['dragenter', 'dragover'].forEach(function(n?: any): any {
            drop.addEventListener(n, function(e?: any): any { e.preventDefault(); drop.classList.add('over'); });
        });
        ['dragleave', 'drop'].forEach(function(n?: any): any {
            drop.addEventListener(n, function(e?: any): any { e.preventDefault(); drop.classList.remove('over'); });
        });
        drop.addEventListener('drop', function(e?: any): any { gfAdd(v, e.dataTransfer.files); });
        gfSync(v);
    }

    // ═══ เริ่มต้นหน้า ═══════════════════════════════════════════════════

    $$('.aih-gen:not(.real), .aih-player').forEach(function(el?: any): any {
        el.insertAdjacentHTML('afterbegin', SCENE);
    });
    /* ป้าย "ตัวอย่างผลลัพธ์" — หายไปเมื่อได้ผลจริงครั้งแรก */
    $$('.aih-view[data-tool] .aih-out-title').forEach(function(t?: any): any {
        t.insertAdjacentHTML('afterend', '<span class="aih-pill aih-sample">ตัวอย่างผลลัพธ์</span>');
    });
    $$('.aih-view').forEach(renderFiles);
    if ($('.aih-view[data-tool="code"]')) {
        showCode($('.aih-view[data-tool="code"]'), 0);
    }
    if ($('.aih-view[data-tool="howto"]')) {
        syncSteps($('.aih-view[data-tool="howto"]'));
    }
    renderHome();
    checkService();
    if (tool === 'home') {
        loadUsage();
    }
    if (tool === 'diagram') {
        dgInit();
    }
    if (tool === 'meeting' && current) {
        mtInit(current);
    }
    if (tool === 'gif' && current) {
        gfInit(current);            /* ★ 06/11/2026 สร้างไฟล์ GIF — ทำในเบราว์เซอร์ ไม่มีแชทข้างเคียง ไม่ผ่านเส้น run */
    }
    if (current && tool !== 'home') {
        buildChat(current);
        if (tool === 'image') {
            imInit(current);        /* ★ 06/11/2026 หน้าตาใหม่ของสร้างรูปภาพ (ต้องหลัง buildChat เพราะปุ่มแชทต้องรู้ว่าแผงมีแล้ว) */
        }
        setTimeout(avoidFab, 600);
        listen(window, 'resize', avoidFab);
        listen(document, 'mouseup', function(): any { setTimeout(avoidFab, 50); });
        listen(document, 'touchend', function(): any { setTimeout(avoidFab, 50); });
    }

    // ═══ ★ 24/10/2026 — ประวัติผลลัพธ์ (ai-hub 1.0.17) ════════════════════
    /* แท็บ "ประวัติ" บนการ์ดซ้ายของเครื่องมือที่บริการเก็บประวัติ (GET /tools → history.tools ; doc-analyze, doc-summary, data-analyze, meeting, slides, image, video)
       ผลลัพธ์อยู่ในตาราง aitran.aihub_history ไฟล์ต้นฉบับอยู่ใน S3 — เห็น/ลบได้เฉพาะของตัวเอง (บริการตัดสินจากตัวตนที่ war ใส่)
       เปิดรายการ = วาดผลด้วย RENDER เดิม + แถบ "ผลจากประวัติ" (ดาวน์โหลดต้นฉบับ / ลบ) ; ถามต่อ = บริการเปิดไฟล์จาก S3 ให้ใหม่ (reopen) */

    var HIST: any = {cfg: null, items: {}, totals: {}, more: {}, loaded: {}, stale: {}, open: {}, item: {}};

    function histOn(t?: any): any {
        return !!(HIST.cfg && HIST.cfg.enabled && (HIST.cfg.tools || []).indexOf(t) >= 0);
    }

    function histForm(action?: any, extra?: any): any {
        var f: any = new FormData();
        f.append('action', action);
        Object.keys(extra || {}).forEach(function(k?: any): any {
            f.append(k, extra[k]);
        });
        return f;
    }

    /** วันเวลาแบบ วว/ดด/ปปปป ชช:นน (ค.ศ. แบบเดียวกับทั้งระบบ) */
    function fmtWhen(iso?: any): any {
        var d: any = new Date(iso);
        if (isNaN(d.getTime())) {
            return '';
        }
        var p: any = function(n?: any): any { return ('0' + n).slice(-2); };
        return p(d.getDate()) + '/' + p(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' + p(d.getHours()) + ':' + p(d.getMinutes());
    }

    function histMount(v?: any): any {
        var t: any = v.getAttribute('data-tool');
        var card: any = $('.aih-input', v);
        if (!histOn(t) || !card || $('.aih-hist-tabs', card)) {
            return;
        }
        var tabs: any = document.createElement('div');
        tabs.className = 'aih-hist-tabs';
        tabs.innerHTML = '<button type="button" class="aih-hist-tab on" data-hist-tab="new"><i class="fa-solid fa-wand-magic-sparkles"></i> '
                + ((<any>{'doc-analyze': 'วิเคราะห์ใหม่', 'doc-summary': 'สรุปใหม่', 'data-analyze': 'วิเคราะห์ใหม่', meeting: 'สรุปใหม่',
                    slides: 'สร้างใหม่', image: 'สร้างใหม่', video: 'สร้างใหม่', music: 'สร้างใหม่', code: 'เขียนใหม่', strategy: 'วิเคราะห์ใหม่', howto: 'สร้างใหม่', diagram: 'สร้างใหม่', 'library-ask': 'ถามใหม่', 'doc-compare': 'เปรียบเทียบใหม่', social: 'สร้างใหม่',
                    'code-review': 'รีวิวใหม่', 'sql-assist': 'งานใหม่', 'log-doctor': 'วิเคราะห์ใหม่', 'code-docs': 'สร้างใหม่',
                    quiz: 'สร้างใหม่', faq: 'สร้างใหม่', 'project-plan': 'วางแผนใหม่', decision: 'วิเคราะห์ใหม่',
                    'formal-writer': 'เขียนใหม่', 'reply-draft': 'ร่างใหม่', 'hr-docs': 'สร้างใหม่', article: 'เขียนใหม่', voiceover: 'สร้างใหม่', 'doc-extract': 'ดึงใหม่',
                    'doc-check': 'ตรวจใหม่'})[t]
                        || 'งานใหม่') + '</button>'
                + '<button type="button" class="aih-hist-tab" data-hist-tab="list"><i class="fa-solid fa-clock-rotate-left"></i> ประวัติ'
                + ' <span class="cnt" data-hist-count=""></span></button>';
        card.insertBefore(tabs, card.firstChild);
        var pane: any = document.createElement('div');
        pane.className = 'aih-hist aih-hist-off';
        pane.innerHTML = '<input type="search" class="aih-in aih-hist-q" maxlength="100" placeholder="ค้นหาชื่อไฟล์ ประเภทเอกสาร หรือคำถาม"/>'
                + '<div class="aih-hist-list"></div>'
                + '<button type="button" class="aih-btn aih-btn-sm aih-hist-more aih-hist-off" data-hist-more="">'
                + '<i class="fa-solid fa-angles-down"></i> ดูรายการเก่ากว่า</button>'
                + '<div class="aih-hint aih-hist-note"><i class="fa-solid fa-lock"></i> เห็นเฉพาะของคุณ'
                + (HIST.cfg.keepsFiles ? ' · เก็บไฟล์ต้นฉบับไว้ ' + esc(HIST.cfg.fileDays) + ' วัน (ดาวน์โหลด/ถามต่อได้จนครบกำหนด)'
                        : ' · ไม่ได้เก็บไฟล์ต้นฉบับ (เปิดดูผลได้ แต่ถามต่อไม่ได้)') + '</div>';
        card.insertBefore(pane, tabs.nextSibling);
        histLoad(v, false);              /* โหลดเงียบ ๆ ให้รู้จำนวนรายการบนแท็บ */
    }

    function histTab(v?: any, which?: any): any {
        var card: any = $('.aih-input', v);
        var list: any = which === 'list';
        $$('.aih-hist-tab', card).forEach(function(b?: any): any {
            b.classList.toggle('on', b.getAttribute('data-hist-tab') === which);
        });
        $('.aih-hist', card).classList.toggle('aih-hist-off', !list);
        ['.aih-input-body', '.aih-input-foot'].forEach(function(s?: any): any {
            var el: any = $(s, card);
            if (el) {
                el.classList.toggle('aih-hist-off', list);
            }
        });
        if (list && (!HIST.loaded[v.getAttribute('data-tool')] || HIST.stale[v.getAttribute('data-tool')])) {
            histLoad(v, false);
        }
    }

    function histLoad(v?: any, older?: any): any {
        var t: any = v.getAttribute('data-tool');
        var box: any = $('.aih-hist-list', v);
        if (!box) {
            return;
        }
        var items: any = older ? (HIST.items[t] || []) : [];
        var extra: any = {tool: t, limit: 30};
        if (older && items.length) {
            extra.before = items[items.length - 1].at;
        }
        if (!older && !HIST.loaded[t]) {
            box.innerHTML = '<div class="aih-status"><span class="aih-orb"></span><span>กำลังโหลดประวัติ…</span></div>';
        }
        return call('history', histForm('list', extra)).then(function(res?: any): any {
            var r: any = res.result || {};
            var got: any = r.items || [];
            // งานที่เพิ่งเสร็จ บริการอาจยังบันทึกไม่ทัน (ส่งไฟล์ขึ้น S3 ก่อนเขียนฐาน) — คงรายการชั่วคราวไว้ 2 นาที
            var pending: any = older ? [] : (HIST.items[t] || []).filter(function(x?: any): any {
                return x.pending && Date.now() - x.pending < 120000 && !got.some(function(g?: any): any { return g.id === x.id; });
            });
            HIST.items[t] = pending.concat(items, got);
            HIST.totals[t] = (r.total || 0) + pending.length;
            HIST.more[t] = !!r.more;
            HIST.loaded[t] = true;
            HIST.stale[t] = false;
            histRender(v);
        }).catch(function(err?: any): any {
            box.innerHTML = '<div class="aih-note warn"><i class="fa-solid fa-triangle-exclamation"></i><span>' + esc(err.message) + '</span></div>';
        });
    }

    function histRender(v?: any): any {
        var t: any = v.getAttribute('data-tool');
        if (t === 'image') {
            imFolderRender(v);      /* ★ 06/11/2026 แท็บ My Folder ใช้ข้อมูลชุดเดียวกับรายการประวัติ */
        }
        var box: any = $('.aih-hist-list', v);
        if (!box) {
            return;
        }
        var q: any = (($('.aih-hist-q', v) || {}).value || '').trim().toLowerCase();
        var all: any = HIST.items[t] || [];
        var shown: any = all.filter(function(it?: any): any {
            return !q || [it.title, it.subtitle || it.documentType, it.question, it.summary].join(' ').toLowerCase().indexOf(q) >= 0;
        });
        var cnt: any = $('[data-hist-count]', v);
        if (cnt) {
            cnt.textContent = HIST.totals[t] ? fmtNum(HIST.totals[t]) : '';
        }
        var more: any = $('.aih-hist-more', v);
        if (more) {
            more.classList.toggle('aih-hist-off', !HIST.more[t]);
        }
        if (!all.length) {
            box.innerHTML = '<div class="aih-empty-list">ยังไม่มีประวัติ — ผลครั้งต่อไปจะถูกเก็บไว้ที่นี่</div>';
            return;
        }
        if (!shown.length) {
            box.innerHTML = '<div class="aih-hint">ไม่พบรายการที่ตรงกับ “' + esc(q) + '” ในรายการที่โหลดมา</div>';
            return;
        }
        box.innerHTML = shown.map(function(it?: any): any {
            // นับเฉพาะไฟล์ของผู้ใช้ (รายงาน / บทถอดเสียงของสรุปการประชุมเป็นไฟล์ที่ระบบสร้าง)
            var files: any = (it.files || []).filter(function(f?: any): any { return (f.kind || 'input') !== 'output'; });
            var ext: any = (String((files[0] || {}).name || it.title || '').split('.').pop() || '').toLowerCase();
            var ic: any = FILE_ICON[ext] || ['doc', 'fa-file-lines'];
            /* ★ 18/11/2026 — สรุปการประชุม: บรรทัดบน = ชื่อการประชุม, บรรทัดล่าง = ชื่อไฟล์ (สลับจากเดิม)
               ไม่มีชื่อการประชุม (ยังสรุปไม่เสร็จ) = คงแบบเดิม */
            var head: any = it.title, line2: any = it.subtitle || it.documentType;
            if (t === 'meeting' && it.subtitle && it.subtitle !== it.title) {
                head = it.subtitle;
                line2 = it.title;
            }
            var conf: any = it.confidence != null ? 'มั่นใจ ' + it.confidence + '%' : '';
            var outs: any = t === 'image' && it.outputs ? it.outputs + ' ภาพ' : '';
            var talkN: any = it.questions ? 'คุยต่อ ' + it.questions + ' ครั้ง' : '';
            /* ★ 18/11/2026 — สรุปการประชุม: วันที่อยู่หน้าชื่อไฟล์ ; โฮเวอร์ที่รายการ = ชื่อการประชุมเต็ม */
            /* ★ 18/11/2026 — ทุกโมดูล: วันที่อยู่หน้าบรรทัดล่าง ; โฮเวอร์ = ข้อความเต็มของรายการ (ชื่อ + บรรทัดรอง + โจทย์) */
            var sub: any = [fmtWhen(it.at), line2, conf, outs, talkN].filter(Boolean).join(' · ');
            var tip: any = t === 'meeting' ? (head || 'เปิดผลนี้')
                : [head, line2, it.question].filter(Boolean).join('\n') || 'เปิดผลนี้';
            return '<div class="aih-hist-item' + (HIST.open[t] === it.id ? ' on' : '') + '">'
                    + '<button type="button" class="aih-hist-open" data-hist-open="' + esc(it.id) + '" title="' + esc(tip) + '">'
                    + '<span class="ft ' + ic[0] + '"><i class="fa-solid ' + ic[1] + '"></i></span>'
                    + '<span class="tx"><b>' + esc(head || 'ไม่มีชื่อ') + (files.length > 1 ? ' <em>+' + (files.length - 1) + ' ไฟล์</em>' : '')
                    + '</b><small>' + esc(sub) + '</small>'
                    + (it.question ? '<small class="qq">' + ((<any>{code: 'โจทย์: ', strategy: 'สถานการณ์: ', howto: 'หัวข้อ: ', diagram: 'โจทย์: ', social: 'โจทย์: ',
                        'sql-assist': 'โจทย์: ', 'code-review': 'บริบท: ', 'log-doctor': 'อาการ: ', quiz: 'หัวข้อ: ', faq: 'เรื่อง: ',
                        'project-plan': 'เป้าหมาย: ', decision: 'เรื่อง: ', 'formal-writer': 'เรื่อง: ', 'reply-draft': 'อยากตอบ: ',
                        'hr-docs': 'ตำแหน่ง: ', article: 'หัวข้อ: ', voiceover: 'สคริปต์: ', 'doc-extract': 'ข้อมูล: ', 'doc-check': 'checklist: '})[t] || 'ถาม: ') + esc(it.question) + '</small>' : '')
                    + '</span></button>'
                    + '<button type="button" class="aih-hist-del" data-hist-del="' + esc(it.id) + '" title="ลบรายการนี้">'
                    + '<i class="fa-regular fa-trash-can"></i></button></div>';
        }).join('');
    }

    function histOpen(v?: any, id?: any): any {
        var t: any = v.getAttribute('data-tool');
        var stop: any = startLoading($('.aih-output', v), ['กำลังเปิดผลจากประวัติ…']);
        call('history', histForm('get', {id: id})).then(function(res?: any): any {
            stop();
            var it: any = res.result || {};
            var r: any = t === 'library-ask' ? libThreadOpen(it) : it.result || {};
            r.historyId = it.id;
            r.historyAt = it.at;        /* ★ 06/11/2026 ชิปวันที่บนหัวผลลัพธ์ของสร้างรูปภาพ */
            r.docId = '';
            HIST.open[t] = it.id;
            HIST.item[t] = it;
            show(v, t, {result: r, model: it.model || {}, models: it.model && it.model.id ? [it.model.id] : [],
                usage: it.usage || {}, elapsedMs: it.elapsedMs || 0, history: it});
            histRestore(v, it);
            histRender(v);
        }).catch(function(err?: any): any {
            stop();
            popup(err.message, 'error', 'เปิดประวัติไม่สำเร็จ');
            histLoad(v, false);
        });
    }

    /** แถบบนผลลัพธ์: เปิดจากประวัติ (วันที่ + ไฟล์ต้นฉบับ + ลบ) หรือ "บันทึกลงประวัติแล้ว" หลังวิเคราะห์ใหม่ */
    function histBanner(v?: any, res?: any): any {
        var body: any = $('.aih-out-body', v);
        var h: any = res.history;
        if (h) {
            // ไฟล์ของผู้ใช้เท่านั้น (ไฟล์ที่ระบบสร้าง เช่น รายงานการประชุม อยู่ที่ปุ่มหัวผลลัพธ์) ; ไฟล์เสียงมีตัวเล่นให้ฟังซ้ำ
            var inputs: any = (h.files || []).filter(function(f?: any): any { return (f.kind || 'input') !== 'output'; });
            var player: any = '';
            var files: any = inputs.map(function(f?: any): any {
                var url: any = API + '/history/' + encodeURIComponent(f.id);
                if (f.available && /^audio\//.test(f.contentType || '') && !player) {
                    player = '<audio controls="controls" preload="none" src="' + url + '"></audio>';
                }
                return f.available
                        ? '<a href="' + url + (player ? '?download=1' : '') + '" target="_blank" rel="noopener" title="เปิด/ดาวน์โหลดไฟล์ต้นฉบับ">'
                        + '<i class="fa-solid fa-download"></i> ' + esc(f.name) + '</a> <span class="sz">' + fmtSize(f.size) + '</span>'
                        : '<span class="gone" title="เก็บไฟล์ต้นฉบับไว้ ' + esc((HIST.cfg || {}).fileDays || '') + ' วัน">'
                        + esc(f.name) + ' (ไฟล์ต้นฉบับหมดอายุแล้ว)</span>';
            }).join(' · ');
            body.insertAdjacentHTML('afterbegin', '<div class="aih-hist-banner"><i class="fa-solid fa-clock-rotate-left"></i>'
                    + '<div><b>ผลจากประวัติ · ' + esc(fmtWhen(h.at)) + '</b>' + (files ? '<small>ไฟล์ต้นฉบับ: ' + files + '</small>' : '')
                    + player + '</div>'
                    + '<button type="button" class="aih-btn aih-btn-sm" data-hist-del="' + esc(h.id) + '"><i class="fa-regular fa-trash-can"></i> ลบ</button></div>');
        } else if (res.historyId) {
            body.insertAdjacentHTML('afterbegin', '<div class="aih-hist-saved"><i class="fa-solid fa-circle-check"></i>'
                    + ' บันทึกลงประวัติแล้ว — เปิดดูย้อนหลังได้ที่แท็บ <b>ประวัติ</b> (เห็นเฉพาะคุณ)</div>');
        }
    }

    /** เวลาของข้อความเก่า: วันนี้ = ชช:นน , วันอื่น = วว/ดด/ปปปป ชช:นน */
    function msgTime(iso?: any): any {
        var d: any = new Date(iso);
        if (isNaN(d.getTime())) {
            return '';
        }
        return d.toDateString() === new Date().toDateString() ? fmtWhen(iso).slice(-5) : fmtWhen(iso);
    }

    /**
     * ★ 24/10/2026 (ai-hub 1.0.18) เปิดรายการจากประวัติ = ได้บทสนทนาเดิมกลับมาด้วย:
     * kind=ask → กล่องถามต่อใต้ผลลัพธ์ , kind=chat → แผงแชทขวา (แทนบทสนทนาที่ค้างอยู่ — ส่วนที่ผูกกับรายการอื่นถูกเก็บไว้แล้ว)
     */
    function histRestore(v?: any, it?: any): any {
        var t: any = v.getAttribute('data-tool');
        var asks: any = [], talk: any = [], q: any = null;
        (it.chat || []).forEach(function(m?: any): any {
            if (m.kind === 'chat') {
                talk.push(m);
            } else if (m.role === 'user') {
                q = m;
            } else if (q) {
                asks.push([q, m]);
                q = null;
            }
        });
        var list: any = $('.aih-out-body .aih-qa-list', v);
        if (list) {
            list.innerHTML = asks.map(function(p?: any): any {
                return '<div class="aih-qa">' + qaHtml(p[0].text, p[1].text, p[1].citations) + '</div>';
            }).join('');
        }
        /* ★ 18/11/2026 แชทไม่ผูกกับรายการผลลัพธ์แล้ว — เปิดผลจากประวัติ = ผลนั้นถูกส่งเข้าแชทต่อเนื่องเดิม (chatOutput ใน show) ไม่สลับ/ล้างแชท
           บทสนทนาเก่าที่เคยผูกกับรายการ (talk) ยังเปิดได้จากปุ่มประวัติแชท เพราะเป็นไฟล์บทสนทนาของเครื่องมือเดียวกัน */
    }

    /** ผลใหม่ที่เพิ่งได้ historyId — ใส่หัวรายการทันที (บริการบันทึกเบื้องหลัง) แล้วโหลดจริงตอนเปิดแท็บครั้งถัดไป */
    function histAdded(v?: any, res?: any): any {
        var t: any = v.getAttribute('data-tool');
        if (!histOn(t)) {
            return;
        }
        var r: any = res.result || {};
        if ((HIST.items[t] || []).some(function(x?: any): any { return x.id === res.historyId; })) {
            return;         /* คำถามต่อในบทสนทนาเดิม (ถามคลังเอกสาร) — รายการเดิม ไม่ใช่รายการใหม่ */
        }
        // ชื่อรายการเหมือนที่บริการตั้ง: ไฟล์แรกที่อัปโหลด ; ไม่มีไฟล์ = ชื่อผล (สไลด์) — fileName ของสไลด์คือไฟล์ .pptx ที่สร้าง ไม่ใช้
        var first: any = (FILES[t] || [])[0] || ((r.documents || [])[0]) || r.file || r.source || {};
        var title: any = first.name || (t === 'meeting' ? r.fileName : r.title || r.prompt || (t === 'library-ask' ? r.question : '')) || '';
        var sub: any = r.documentType || r.title || r.opLabel || '';
        var item: any = {id: res.historyId, at: new Date().toISOString(), title: title,
            subtitle: sub === title ? (r.subtitle || '') : sub, confidence: r.confidence, question: t === 'library-ask' ? '' : r.question || '',
            files: (r.documents || []).map(function(d?: any): any { return {name: d.name}; }), pending: Date.now()};
        HIST.items[t] = [item].concat((HIST.items[t] || []).filter(function(x?: any): any { return x.id !== item.id; }));
        HIST.totals[t] = (HIST.totals[t] || 0) + 1;
        HIST.stale[t] = true;
        histRender(v);
    }

    /** ใส่ค่าในฟอร์มของรายการในประวัติกลับลงฟอร์ม (ช่องข้อความ / ตัวเลือกแบบชิป / select) — ไม่แตะตัวเลือก model */
    function histFillForm(v?: any, req?: any): any {
        $$('.aih-input [data-field]', v).forEach(function(el?: any): any {
            var name: any = el.getAttribute('data-field');
            if (name === 'model' || !Object.prototype.hasOwnProperty.call(req, name)) {
                return;
            }
            var val: any = String(req[name]);
            if (el.classList.contains('aih-chips') || el.classList.contains('aih-skins')) {
                var want: any = val.split(',');
                $$('[data-value],[data-skin]', el).forEach(function(c?: any): any {
                    c.classList.toggle('on', want.indexOf(c.getAttribute('data-value') || c.getAttribute('data-skin')) >= 0);
                });
            } else if (el.type !== 'checkbox' && el.type !== 'file') {
                el.value = val;
            }
        });
        if (v.getAttribute('data-tool') === 'sql-assist') {
            sqlSync(v);
        }
    }

    /** ผลบนจอเปิดมาจากประวัติไหม (ไม่ใช่ผลที่เพิ่งวิเคราะห์) */
    function histShowing(v?: any): any {
        var t: any = v.getAttribute('data-tool');
        return !!(HIST.open[t] && LAST[t] && LAST[t].historyId === HIST.open[t]);
    }

    /** ไฟล์ต้นฉบับของรายการที่เปิดอยู่ (ดาวน์โหลดกลับจาก S3 ผ่าน /aihub/history/{id}) — หมดอายุ = ไม่ได้ */
    function histFiles(v?: any): any {
        var it: any = HIST.item[v.getAttribute('data-tool')] || {};
        var files: any = it.files || [];
        if (!files.length || files.some(function(f?: any): any { return !f.available; })) {
            return Promise.reject(new Error('ไฟล์ต้นฉบับของรายการนี้หมดอายุแล้ว — เลือกไฟล์ใหม่แล้ววิเคราะห์อีกครั้ง'));
        }
        return Promise.all(files.map(function(f?: any): any {
            return env.fetch(API + '/history/' + encodeURIComponent(f.id), {credentials: 'same-origin'}).then(function(r?: any): any {
                if (!r.ok) {
                    throw new Error('ดาวน์โหลดไฟล์ต้นฉบับไม่สำเร็จ — เลือกไฟล์ใหม่แล้ววิเคราะห์อีกครั้ง');
                }
                return r.blob();
            }).then(function(b?: any): any {
                return new File([b], f.name, {type: f.contentType || b.type});
            });
        }));
    }

    function histReopen(id?: any): any {
        return call('history', histForm('reopen', {id: id})).then(function(res?: any): any {
            return (res.result || {}).docId;
        });
    }

    function histDelete(v?: any, id?: any): any {
        var t: any = v.getAttribute('data-tool');
        var text: any = 'ผลลัพธ์ บทสนทนา และไฟล์ต้นฉบับที่เก็บไว้จะถูกลบถาวร กู้คืนไม่ได้';
        var ask: any = (<any>window).swal
                ? swal({title: 'ลบรายการนี้ออกจากประวัติ', text: text, icon: 'warning', buttons: ['ยกเลิก', 'ลบรายการ'], dangerMode: true})
                : Promise.resolve(window.confirm(text));
        ask.then(function(ok?: any): any {
            if (!ok) {
                return;
            }
            return call('history', histForm('delete', {id: id})).then(function(): any {
                HIST.items[t] = (HIST.items[t] || []).filter(function(x?: any): any { return x.id !== id; });
                HIST.totals[t] = Math.max(0, (HIST.totals[t] || 1) - 1);
                if (LAST[t] && LAST[t].historyId === id) {
                    delete LAST[t].historyId;      /* แชทต่อจากนี้ไม่ผูกกับรายการที่ลบแล้ว */
                }
                if (t === 'library-ask' && LIB.hid === id) {
                    LIB.hid = '';                  /* คำถามถัดไปเริ่มรายการใหม่ */
                    if (HIST.open[t] === id) {
                        LIB.thread = [];
                        $('[data-field="history"]', v).value = '';
                    }
                }
                if (HIST.open[t] === id) {
                    HIST.open[t] = '';
                    HIST.item[t] = null;
                    $('.aih-out-body', v).innerHTML = '<div class="aih-hint"><i class="fa-regular fa-trash-can"></i> ลบรายการนี้ออกจากประวัติแล้ว</div>';
                    var acts: any = $('.aih-out-acts', v);
                    if (acts) {
                        acts.innerHTML = '';
                    }
                }
                histRender(v);
                toast('ลบออกจากประวัติแล้ว');
            });
        }).catch(function(err?: any): any {
            popup(err.message || String(err), 'error', 'ลบไม่สำเร็จ');
        });
    }

    // ═══ เหตุการณ์ (event delegation ที่ root) ═══════════════════════════

    root.addEventListener('input', function(e?: any): any {
        if (e.target.classList.contains('aih-chat-ta')) {
            e.target.style.height = 'auto';
            e.target.style.height = Math.min(110, e.target.scrollHeight) + 'px';
        }
        if (e.target.classList.contains('aih-lib-filter-q')) {
            libRenderList(closest(e.target, '.aih-view'));
        }
        if (e.target.classList.contains('aih-hist-q')) {
            histRender(closest(e.target, '.aih-view'));
        }
    });

    root.addEventListener('click', function(e?: any): any {
        var btn: any = e.target.closest ? e.target.closest('.aih-mp') : null;
        if (btn) {
            e.preventDefault();
            if (mp.btn === btn) {
                mpClose();
            } else {
                mpClose();
                mpOpen(btn);
            }
        }
    });

    listen(document, 'keydown', function(e?: any): any {
        if (e.key === 'Escape') {
            var lb: any = document.querySelector('.aih-im-lb');
            if (lb) {
                lb.remove();
            }
            var open: any = $('.aih-lib-modal:not([hidden])');
            if (open) {
                libClose(closest(open, '.aih-view'));
            }
        }
    });

    root.addEventListener('change', function(e?: any): any {
        if (e.target.matches('[data-model-select]') || e.target.matches('[data-chat-model]')
                || e.target.matches('[data-text-model-select]')) {
            var mv: any = closest(e.target, '.aih-view');
            var key: any = e.target.matches('[data-chat-model]') ? 'chat' : mv.getAttribute('data-tool')
                    + (e.target.matches('[data-text-model-select]') ? '-prompt' : '');
            try { window.localStorage.setItem('aihub.model.' + key, e.target.value); } catch (err: any) {}
            if (e.target.matches('[data-model-select]')) {
                syncModelNote(mv);
            } else if (e.target.matches('[data-text-model-select]')) {
                syncTextModelNote(mv);
            } else {
                syncChatModel(mv);
            }
            return;
        }
        var v: any = closest(e.target, '.aih-view');
        if (e.target.matches('.aih-drop input[type=file]')) {
            addFiles(v, e.target.files, closest(e.target, '.aih-drop').getAttribute('data-slot'));
            e.target.value = '';
            return;
        }
        if (e.target.matches('.aih-ed-drop input[type=file]')) {
            edPick(v, e.target.files[0], closest(e.target, '.aih-ed-drop').getAttribute('data-ed-slot'));
            return;
        }
        if (closest(e.target, '.aih-step')) {
            syncSteps(v);
        }
    });

    root.addEventListener('click', function(e?: any): any {
        var t: any = e.target, el: any;
        var v: any = closest(t, '.aih-view');

        if ((el = closest(t, '[data-mock]'))) {
            e.preventDefault();
            mockMsg(el.getAttribute('data-mock'));
            return;
        }
        if (v && v.getAttribute('data-tool') === 'image') {
            /* ★ 06/11/2026 สร้างรูปภาพ — แท็บ / เทมเพลต / My Folder / ภาพอ้างอิง / ปุ่มบนหัวผลลัพธ์ (data-im="คำสั่ง:ค่า") ; คลิกนอกเมนูภาพ = ปิดเมนู */
            var imEl: any = closest(t, '[data-im]');
            if (imEl && imClick(v, imEl, e)) {
                return;
            }
            if (!imEl) {
                imMenuClose(v);
            }
        }
        if ((el = closest(t, '.aih-run'))) {
            run(v);
            return;
        }
        if ((el = closest(t, '[data-hist-tab]'))) {
            histTab(v, el.getAttribute('data-hist-tab'));
            return;
        }
        if ((el = closest(t, '[data-hist-open]'))) {
            histOpen(v, el.getAttribute('data-hist-open'));
            return;
        }
        if ((el = closest(t, '[data-hist-del]'))) {
            histDelete(v, el.getAttribute('data-hist-del'));
            return;
        }
        if ((el = closest(t, '[data-hist-more]'))) {
            histLoad(v, true);
            return;
        }
        if ((el = closest(t, '[data-act]'))) {
            var act: any = el.getAttribute('data-act');
            if (act === 'gd-pick') {
                gdPick(el);
                return;
            } else if (act === 'gd-off') {
                e.preventDefault();
                gdDisconnect();
                return;
            } else if (act === 'ms-pick') {
                msPick(el);
                return;
            } else if (act === 'ms-off') {
                e.preventDefault();
                msDisconnect();
                return;
            } else if (act === 'cv-pick') {
                cvPick(el);
                return;
            } else if (act === 'cv-off') {
                e.preventDefault();
                cvDisconnect();
                return;
            } else if (act === 'cloud-save') {
                cloudSave(el);
                return;
            }
            if (act === 'reset') {
                $$('.aih-input textarea, .aih-input input[type=text]', v).forEach(function(x?: any): any { x.value = ''; });
                FILES[v.getAttribute('data-tool')] = [];
                renderFiles(v);
                if (v.getAttribute('data-tool') === 'image') {
                    edReset(v);
                    $('[data-field="count"]', v).value = '1';    /* ช่องจำนวนภาพเป็น input — ถูกล้างเป็นว่างพร้อมช่องข้อความอื่น */
                    imRefClear(v);
                }
                if (v.getAttribute('data-tool') === 'customer-brief') {
                    cbClear(v);
                }
            } else if (act === 'cb-copy') {
                var cd: any = ((LAST['customer-brief'] || {}).drafts || [])[Number(el.getAttribute('data-i'))];
                if (cd) {
                    copyText(cbName((cd.subject ? cd.subject + '\n\n' : '') + cd.text));
                }
            } else if (act === 'cb-change') {
                cbClear(v);
            } else if (act === 'cb-preview') {
                e.preventDefault();
                cbPreview(v);
            } else if (act === 'soc-copy' || act === 'soc-image') {
                var sp: any = socItem(el);
                if (sp && act === 'soc-copy') {
                    copyText(sp.caption + ((sp.hashtags || []).length ? '\n\n' + sp.hashtags.join(' ') : ''));
                } else if (sp) {
                    socToImage(sp.imagePrompt);
                }
            } else if (act === 'soc-csv') {
                socCsv();
            } else if (act === 'swap-files') {
                var sw: any = filesOf(v);
                FILES[v.getAttribute('data-tool')] = [sw[1], sw[0]];
                renderFiles(v);
            } else if (act === 'ed-continue') {
                edContinue(v, Number(el.getAttribute('data-i') || 0));
            } else if (act === 'ed-undo' || act === 'ed-clear') {
                ED.strokes = act === 'ed-clear' ? [] : ED.strokes.slice(0, -1);
                edRedraw(v);
                edSync(v);
            } else if (act === 'ask') {
                ask(closest(el, '.aih-ask'));
            } else if (act === 'again') {
                if (v.getAttribute('data-tool') === 'image' && histShowing(v) && ((HIST.item.image || {}).request || {}).op === 'style-guide') {
                    imRegenerate(v, HIST.open.image);       /* ★ 06/11/2026 ผลสร้างตามภาพอ้างอิงที่เปิดจากประวัติ — คำบรรยาย/ภาพอ้างอิงอยู่คนละรูปแบบกับฟอร์มปกติ */
                    return;
                }
                // ★ 24/10/2026 ผลจากประวัติ: ใช้ค่าในฟอร์มของรายการนั้น (ค่าที่ค้างในหน้าอาจเป็นของงานอื่น)
                if (histShowing(v)) {
                    histFillForm(v, (HIST.item[v.getAttribute('data-tool')] || {}).request || {});
                    histTab(v, 'new');
                }
                if (v.getAttribute('data-tool') === 'image') {
                    /* ปุ่มนี้มีเฉพาะภาพที่สร้างจากคำบรรยาย — รายการเก่าไม่มีช่อง mode จึงตั้งเป็นโหมดสร้างภาพเอง */
                    $$('.aih-chips[data-field="mode"] .aih-chip', v).forEach(function(c?: any): any {
                        c.classList.toggle('on', c.getAttribute('data-value') === 'generate');
                    });
                    edSync(v);
                }
                run(v);
            } else if (act === 'chat-send') {
                chatSend(v);
            } else if (act === 'chat-copy') {
                var cm: any = (CHATS[v.getAttribute('data-tool')] || [])[Number(el.getAttribute('data-i'))];
                if (cm) {
                    copyText(cm.text);
                }
            } else if (act === 'copy-lyrics') {
                if (SONG) {
                    copyText(lyricSheet(SONG));
                }
            } else if (act === 'copy-out') {
                copyText(SECS_TOOLS[v.getAttribute('data-tool')] && LAST[v.getAttribute('data-tool')]
                        ? secsText(LAST[v.getAttribute('data-tool')]) : $('.aih-out-body', v).innerText);
            } else if (act === 'download-out') {
                var title: any = $('.aih-out-title', v).textContent.trim();
                var secsR: any = SECS_TOOLS[v.getAttribute('data-tool')] && LAST[v.getAttribute('data-tool')];
                downloadText(safeName(title) + (secsR ? '.md' : '.txt'), secsR ? secsText(secsR) : $('.aih-out-body', v).innerText,
                        secsR ? 'text/markdown' : '');
            } else if (act === 'pdf-out') {
                pdfOut(v, el);
            } else if (act === 'pdf-minutes' || act === 'pdf-transcript') {
                meetPdf(el, act === 'pdf-minutes' ? 'minutes' : 'transcript');
            } else if (act === 'copy-vo') {
                copyText((LAST.voiceover || {}).script || '');
            } else if (act === 'vo-edit') {
                /* ★ 25/10/2026 เสียงพากย์: เอาคำอ่านที่ AI ปรับแล้วมาแก้ต่อเอง — ไม่ให้ AI ปรับซ้ำ */
                $('[data-field="script"]', v).value = (LAST.voiceover || {}).script || '';
                $('[data-field="normalize"]', v).checked = false;
                if ($('.aih-hist-tabs', v)) {
                    histTab(v, 'new');
                }
                $('[data-field="script"]', v).focus();
            } else if (act === 'vo-from-video') {
                try { sessionStorage.setItem('aihub.voice.script', (LAST.video || {}).narration || ''); } catch (e: any) {}
                window.location.href = toolLink('voiceover');
            } else if (act === 'copy-snip' || act === 'download-snip') {
                var sn: any = SNIPS[Number(el.getAttribute('data-snip'))];
                if (sn && act === 'copy-snip') {
                    copyText(sn.content);
                } else if (sn) {
                    downloadText(safeName(sn.name) + '.' + snipExt(sn.language), sn.content);
                }
            } else if (act === 'download-code') {
                var f: any = CODE_FILES[curCode];
                if (f) {
                    downloadText(safeName(f.name), f.content || '');
                }
            } else if (act === 'meet-retry') {
                var mj: any = (closest(el, '[data-meet]') || el).getAttribute('data-meet');
                if (mj) {
                    pollMeeting(v, mj, Date.now());
                }
            } else if (act === 'dg-png' || act === 'dg-svg') {
                dgExport(act === 'dg-png' ? 'png' : 'svg');
            } else if (act === 'dg-drawio') {
                if (DG.xml) {
                    downloadText(safeName(DG.title || 'แผนภาพ') + '.drawio', DG.xml, 'application/vnd.jgraph.mxfile');
                }
            } else if (act === 'dg-full') {
                dgFull(v);
            } else if (act === 'lib-open') {
                libOpen(v);
            } else if (act === 'lib-close') {
                libClose(v);
            } else if (act === 'lib-new') {
                libNew(v);
            } else if (act === 'lib-upload') {
                libUpload(v, el);
            } else if (act === 'lib-save') {
                libSave(v, el);
            } else if (act === 'lib-cancel') {
                LIB.editing = '';
                libRenderList(v);
            } else if (act === 'clear-recent') {
                e.preventDefault();
                saveRecent([]);
                renderHome();
            }
            return;
        }
        if ((el = closest(t, '[data-sheet]'))) {
            // วิเคราะห์ข้อมูล: วิเคราะห์ชีตอื่นของไฟล์เดิม
            var sheetField: any = $('[data-field="sheet"]', v);
            if (sheetField && histShowing(v)) {
                // ★ 24/10/2026 ผลจากประวัติ: ใช้ไฟล์ต้นฉบับที่เก็บไว้ (ไฟล์ที่เลือกค้างในหน้าอาจเป็นคนละไฟล์)
                var sheet: any = el.getAttribute('data-sheet');
                histFiles(v).then(function(files?: any): any {
                    FILES[v.getAttribute('data-tool')] = files;
                    renderFiles(v);
                    sheetField.value = sheet;
                    histTab(v, 'new');
                    run(v);
                }).catch(function(err?: any): any {
                    popup(err.message, 'error', 'วิเคราะห์ชีตอื่นไม่ได้');
                });
            } else if (sheetField) {
                sheetField.value = el.getAttribute('data-sheet');
                run(v);
            }
            return;
        }
        // ถามคลังเอกสาร: คำถามต่อเนื่อง / หมวด / แท็บและปุ่มในหน้าต่างคลัง / คลิกพื้นหลังเพื่อปิด
        if ((el = closest(t, '[data-lib-follow]'))) {
            $('[data-field="question"]', v).value = el.getAttribute('data-lib-follow');
            run(v);
            return;
        }
        if ((el = closest(t, '[data-lib-cat]'))) {
            $('[data-field="category"]', v).value = el.getAttribute('data-lib-cat');
            $$('[data-lib-cat]', v).forEach(function(c?: any): any { c.classList.toggle('on', c === el); });
            return;
        }
        if ((el = closest(t, '[data-lib-tab]'))) {
            libTab(v, el.getAttribute('data-lib-tab'));
            return;
        }
        if ((el = closest(t, '[data-lib-edit]'))) {
            LIB.editing = el.getAttribute('data-lib-edit');
            libRenderList(v);
            return;
        }
        if ((el = closest(t, '[data-lib-del]'))) {
            libDelete(v, el.getAttribute('data-lib-del'));
            return;
        }
        if (t.classList && t.classList.contains('aih-lib-modal')) {
            libClose(v);
            return;
        }
        if ((el = closest(t, '[data-chat]')) && v) {
            var ck: any = el.getAttribute('data-chat');
            if (ck === 'hist') { chatHistOpen(v); }
            else if (ck === 'new') { chatNew(v); }
            else if (ck === 'dl') { var dm: any = $('.aih-chat-dlm', v); chatPanel(v, dm && dm.hidden ? 'dl' : ''); }
            else if (ck === 'dl-md') { chatDownload(v, 'md', el); }
            else if (ck === 'dl-pdf') { chatDownload(v, 'pdf', el); }
            return;
        }
        if ((el = closest(t, '[data-chat-ap]')) && v) {
            if (el.getAttribute('data-chat-ap') === 'apply') {
                chatApply(v, Number(el.getAttribute('data-i')));
            } else {
                var sm: any = (CHATS[v.getAttribute('data-tool')] || [])[Number(el.getAttribute('data-i'))];
                if (sm && sm.astate === 'pending') { sm.astate = 'skipped'; renderChat(v, false); }
            }
            return;
        }
        if ((el = closest(t, '[data-chat-h]')) && v) {
            e.stopPropagation();
            chatHistClick(v, el.getAttribute('data-chat-h'));
            return;
        }
        if ((el = closest(t, '[data-chat-q]'))) {
            chatSend(v, el.getAttribute('data-chat-q'));
            return;
        }
        if ((el = closest(t, '[data-seek]'))) {
            var audio: any = $('.aih-audio', v);
            if (audio) {
                audio.currentTime = Number(el.getAttribute('data-seek')) || 0;
                audio.play();
            }
            return;
        }
        if ((el = closest(t, '.aih-file .rm'))) {
            filesOf(v).splice(Number(el.getAttribute('data-rm')), 1);
            renderFiles(v);
            return;
        }
        if ((el = closest(t, '.aih-drop[data-files]'))) {
            if (t.tagName !== 'INPUT') {
                $('input[type=file]', el).click();
            }
            return;
        }
        if ((el = closest(t, '[data-fill]'))) {
            var topic: any = $('[data-field="topic"]', v) || $('.aih-input textarea[data-field]', v);
            if (topic) {
                topic.value = el.getAttribute('data-fill');
                topic.focus();
            }
            // ตัวอย่างที่ผูกกับชนิดแผนภาพ เลือกชนิดให้ด้วย
            var fillType: any = el.getAttribute('data-fill-type');
            var typeGroup: any = fillType && $('[data-field="type"]', v);
            if (typeGroup) {
                $$('.aih-chip', typeGroup).forEach(function(c?: any): any { c.classList.toggle('on', c.getAttribute('data-value') === fillType); });
            }
            // ★ 25/10/2026 ชุดคอลัมน์สำเร็จรูปของ "ดึงข้อมูลเป็นตาราง" เลือกแบบตารางให้ด้วย (ใบเสนอราคา = แถวละรายการสินค้า)
            var fillMode: any = el.getAttribute('data-fill-mode');
            var modeGroup: any = fillMode && $('[data-field="mode"]', v);
            if (modeGroup) {
                $$('.aih-chip', modeGroup).forEach(function(c?: any): any { c.classList.toggle('on', c.getAttribute('data-value') === fillMode); });
            }
            return;
        }
        if ((el = closest(t, '.aih-ed-drop'))) {
            if (t.tagName !== 'INPUT') {
                $('input[type=file]', el).click();
            }
            return;
        }
        if ((el = closest(t, '.aih-qa-ch[data-pick] li'))) {
            /* ★ 25/10/2026 แบบทดสอบ: ตอบได้ครั้งเดียวต่อข้อ — เขียว = ข้อที่ถูก , แดง = ข้อที่เลือกผิด แล้วเปิดเฉลย */
            var qol: any = el.parentNode;
            if (!qol.hasAttribute('data-done')) {
                qol.setAttribute('data-done', '');
                el.classList.add(el.hasAttribute('data-ok') ? 'ok' : 'bad');
                var qok: any = $('[data-ok]', qol);
                if (qok) {
                    qok.classList.add('ok');
                }
                var qd: any = $('details', closest(qol, '.aih-qa-i'));
                if (qd) {
                    qd.open = true;
                }
            }
            return;
        }
        if ((el = closest(t, '.aih-chip'))) {
            var group: any = el.parentNode;
            if (group.hasAttribute('data-single')) {
                Array.prototype.forEach.call(group.children, function(c?: any): any { c.classList.remove('on'); });
                el.classList.add('on');
            } else {
                el.classList.toggle('on');
            }
            if (v && v.getAttribute('data-tool') === 'social' && group.getAttribute('data-field') === 'mode') {
                socSync(v);
            }
            /* ★ 1.0.57 ทำสไลด์: ชิปจำนวนหน้าเป็นแค่ทางลัด ค่าจริงอยู่ในช่องกรอก (ว่าง = เท่าไฟล์เดิม) */
            if (v && v.getAttribute('data-tool') === 'slides' && group.hasAttribute('data-count-pick')) {
                sdSetCount(v, Number(el.getAttribute('data-value')) || 0);
            }
            if (v && v.getAttribute('data-tool') === 'sql-assist' && group.getAttribute('data-field') === 'mode') {
                sqlSync(v);
            }
            if (v && v.getAttribute('data-tool') === 'voiceover' && group.getAttribute('data-field') === 'voice') {
                voSync(v);
            }
            if (v && v.getAttribute('data-tool') === 'voiceover' && group.classList.contains('aih-vo-prov')) {
                voFilter(v);
            }
            if (v && v.getAttribute('data-tool') === 'image' && closest(group, '.aih-input')) {
                var ef2: any = group.getAttribute('data-field');
                if (ef2 === 'mode' || ef2 === 'op') {
                    ED.show = true;          /* เปลี่ยนเป็นแก้ไขภาพ / เปลี่ยนคำสั่ง = กลับมาที่ภาพที่จะแก้ */
                }
                edSync(v);
            }
            var ratio: any = el.getAttribute('data-ratio');
            var gens: any = v && $('.aih-out-body:not([data-real]) .aih-gens', v);
            if (ratio && gens) {
                gens.setAttribute('data-ratio', ratio);
            }
            return;
        }
        if ((el = closest(t, '.aih-skin'))) {
            Array.prototype.forEach.call(el.parentNode.children, function(c?: any): any { c.classList.remove('on'); });
            el.classList.add('on');
            /* ตัวอย่างเปลี่ยนตามทันที ; ผลจริงไม่เปลี่ยน เพราะไฟล์ .pptx สร้างไปแล้วด้วยธีมเดิม */
            var deck: any = v && $('.aih-deck:not([data-real])', v);
            if (deck) {
                deck.setAttribute('data-skin', el.getAttribute('data-skin'));
            }
            return;
        }
        if ((el = closest(t, '.aih-thumb'))) {
            var thumbs: any = el.parentNode.children, idx: any = 0;
            Array.prototype.forEach.call(thumbs, function(c?: any, i?: any): any {
                c.classList.toggle('on', c === el);
                if (c === el) {
                    idx = i;
                }
            });
            var main: any = $('.aih-deck-main .aih-slide', v);
            if (main) {
                $('.s-kicker', main).textContent = el.getAttribute('data-kicker');
                $('.s-title', main).textContent = el.getAttribute('data-title');
                $('.s-sub', main).textContent = el.getAttribute('data-sub');
            }
            var cap: any = $('#aihSlideCap', v);
            if (cap) {
                cap.textContent = 'สไลด์ ' + (idx + 1) + ' / ' + thumbs.length + ' · ' + el.getAttribute('data-cap');
            }
            return;
        }
        if ((el = closest(t, '.aih-play'))) {
            var player: any = closest(el, '.aih-player');
            var playing: any = player.classList.toggle('playing');
            el.innerHTML = playing ? '<i class="fa-solid fa-pause"></i>' : '<i class="fa-solid fa-play"></i>';
            return;
        }
        if ((el = closest(t, '.aih-code-tab'))) {
            showCode(v, Number(el.getAttribute('data-file')));
            return;
        }
        if ((el = closest(t, '.aih-copy-code'))) {
            var cf: any = CODE_FILES[curCode];
            if (cf) {
                copyText(cf.content || '');
            }
        }
    });

    /* ลากไฟล์มาวาง */
    ['dragenter', 'dragover'].forEach(function(type?: any): any {
        root.addEventListener(type, function(e?: any): any {
            var drop: any = closest(e.target, '.aih-drop[data-files]');
            if (drop) {
                e.preventDefault();
                drop.classList.add('drag');
            }
        });
    });
    ['dragenter', 'dragover'].forEach(function(type?: any): any {
        root.addEventListener(type, function(e?: any): any {
            var drop: any = closest(e.target, '.aih-ed-drop') || closest(e.target, '.aih-ed-stage');
            if (drop) {
                e.preventDefault();
                drop.classList.add('drag');
            }
        });
    });
    ['dragleave', 'drop'].forEach(function(type?: any): any {
        root.addEventListener(type, function(e?: any): any {
            var drop: any = closest(e.target, '.aih-ed-drop') || closest(e.target, '.aih-ed-stage');
            if (!drop) {
                return;
            }
            e.preventDefault();
            drop.classList.remove('drag');
            if (type === 'drop' && e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]) {
                edPick(closest(drop, '.aih-view'), e.dataTransfer.files[0], drop.getAttribute('data-ed-slot') || 'image');
            }
        });
    });
    ['dragleave', 'drop'].forEach(function(type?: any): any {
        root.addEventListener(type, function(e?: any): any {
            var drop: any = closest(e.target, '.aih-drop[data-files]');
            if (!drop) {
                return;
            }
            e.preventDefault();
            drop.classList.remove('drag');
            if (type === 'drop' && e.dataTransfer && e.dataTransfer.files) {
                addFiles(closest(drop, '.aih-view'), e.dataTransfer.files, drop.getAttribute('data-slot'));
            }
        });
    });

    /* Enter ในช่องกรอกจะ submit ฟอร์ม JSF ทั้งหน้า (โหลดหน้าใหม่) — กันไว้ ; ช่อง "ถามต่อ" = ส่งคำถาม */
    root.addEventListener('keydown', function(e?: any): any {
        if ((e.key === 'Enter' || e.keyCode === 13) && !e.shiftKey && !e.isComposing && e.target.classList.contains('aih-chat-ta')) {
            e.preventDefault();
            chatSend(closest(e.target, '.aih-view'));
            return;
        }
        if ((e.key === 'Enter' || e.keyCode === 13) && e.target.tagName === 'INPUT') {
            e.preventDefault();
            var box: any = closest(e.target, '.aih-ask');
            if (box) {
                ask(box);
            }
        }
    });

    /* หน้ารวม: ค้นหาเครื่องมือ (ชื่อกลุ่มตรง = แสดงทุกเครื่องมือในกลุ่ม) */
    var search: any = document.getElementById('aihSearch');
    if (search) {
        search.addEventListener('input', function(): any {
            var q: any = search.value.trim().toLowerCase();
            var any: any = false;
            $$('.aih-group').forEach(function(g?: any): any {
                var head: any = $('.aih-group-head', g).textContent.toLowerCase();
                var groupHit: any = q && head.indexOf(q) !== -1;
                var shown: any = 0;
                $$('.aih-tool', g).forEach(function(a?: any): any {
                    var hay: any = (a.textContent + ' ' + (a.getAttribute('data-k') || '')).toLowerCase();
                    var ok: any = !q || groupHit || hay.indexOf(q) !== -1;
                    a.style.display = ok ? '' : 'none';
                    if (ok) {
                        shown++;
                    }
                });
                g.style.display = shown ? '' : 'none';
                var cnt: any = $('.aih-group-count', g);
                if (cnt) {
                    cnt.textContent = shown + ' เครื่องมือ';
                }
                if (shown) {
                    any = true;
                }
            });
            (<any>document.getElementById('aihEmpty')).style.display = any ? 'none' : '';
        });
    }

    /* ★ 18/10/2026 — ช่องค้นหาบนแบนเนอร์เป็นปุ่มไอคอนด้านขวา (user สั่ง) คลิก หรือกด / แล้วค่อยขยายเป็นช่องกรอก
       ปิด: Esc หรือกากบาท = ล้างคำค้น + ปิด ; คลิกที่อื่นตอนช่องว่าง = ปิดเฉย ๆ (มีคำค้นค้างไว้ = เปิดค้าง ผลกรองไม่หาย) */
    var sbox: any = document.getElementById('aihSearchBox');
    if (sbox && search) {
        var sbtn: any = sbox.querySelector('.aih-search-btn');
        var openSearch: any = function(): any {
            sbox.classList.add('open');
            sbtn.setAttribute('aria-expanded', 'true');
            search.focus();
        };
        var closeSearch: any = function(clear?: any): any {
            if (clear && search.value) {
                search.value = '';
                search.dispatchEvent(new Event('input'));
            }
            sbox.classList.remove('open');
            sbtn.setAttribute('aria-expanded', 'false');
        };
        sbox.addEventListener('click', function(e?: any): any {
            if (closest(e.target, '.aih-search-x')) {
                e.preventDefault();
                closeSearch(true);
                sbtn.focus();
                return;
            }
            if (!sbox.classList.contains('open')) {
                e.preventDefault();
                openSearch();
            } else {
                search.focus();
            }
        });
        search.addEventListener('keydown', function(e?: any): any {
            if (e.key === 'Escape') {
                closeSearch(true);
                sbtn.focus();
            }
        });
        search.addEventListener('blur', function(): any {
            setTimeout(function(): any {
                if (!search.value.trim() && !sbox.contains(document.activeElement)) {
                    closeSearch(false);
                }
            }, 150);
        });
        listen(document, 'keydown', function(e?: any): any {
            var tag: any = (e.target.tagName || '').toLowerCase();
            if (e.key === '/' && !e.ctrlKey && !e.metaKey && !e.altKey && tag !== 'input' && tag !== 'textarea'
                    && tag !== 'select' && !e.target.isContentEditable) {
                e.preventDefault();
                openSearch();
            }
        });
    }

    // ═══ หน้าผู้ดูแลระบบ AI HUB (1.0.60 โครงหน้า · 1.0.71 ยอด token จริง · 1.0.79 ทุกแท็บเป็นข้อมูลจริง) ═══════════
    /* ★ 1.0.80 ยอดเป็นบาท = ต้นทุน USD × อัตราที่ตั้งในบริการ (aihub.pricing.thb-per-usd) — ไม่ฮาร์ดโค้ดในหน้าจอ ; 0 / ไม่ตั้ง = ไม่แสดงเป็นบาท */
    function admThb(usd?: any, rate?: any): any {
        return rate > 0 ? '≈ ' + admBaht((usd || 0) * rate) + ' (อัตรา ' + rate + ' บาท/USD ที่ตั้งไว้)' : 'ไม่ได้ตั้งอัตราบาท (aihub.pricing.thb-per-usd)';
    }









    function admNum(n?: any): any {
        return Math.round(n).toLocaleString('en-US');
    }

    function admBaht(n?: any): any {
        return admNum(n) + ' บาท';
    }


    /* กราฟเส้น 30 วัน — SVG ล้วน ไม่มีไลบรารี */
    function admLine(days?: any, color?: any, h?: any, unit?: any, lastText?: any): any {
        h = h || 120;
        unit = unit || 'เครดิต';
        var w: any = 560, max: any = Math.max.apply(null, days.map(function(x?: any): any { return x.v; })) || 1;
        var step: any = w / (days.length - 1);
        var pts: any = days.map(function(x?: any, i?: any): any { return [i * step, h - (x.v / max) * (h - 18) - 6]; });
        var line: any = pts.map(function(p?: any, i?: any): any { return (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1); }).join(' ');
        var area: any = line + ' L' + w + ' ' + h + ' L0 ' + h + ' Z';
        var grid: any = [0.25, 0.5, 0.75].map(function(g?: any): any {
            return '<line x1="0" y1="' + (h * g).toFixed(1) + '" x2="' + w + '" y2="' + (h * g).toFixed(1) + '" class="adm-grid"/>';
        }).join('');
        var last: any = days[days.length - 1];
        return '<svg class="adm-svg" viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none" role="img" '
                + 'aria-label="กราฟการใช้เครดิต 30 วัน">' + grid
                + '<path d="' + area + '" fill="' + color + '" opacity=".12"/>'
                + '<path d="' + line + '" fill="none" stroke="' + color + '" stroke-width="2" stroke-linejoin="round"/>'
                + '<circle cx="' + (w).toFixed(1) + '" cy="' + pts[pts.length - 1][1].toFixed(1) + '" r="3.5" fill="' + color + '"/>'
                + '</svg><div class="adm-axis"><span>' + days[0].d.getDate() + '/' + (days[0].d.getMonth() + 1) + '</span>'
                + '<span>' + (lastText || 'วันนี้') + ' ' + admNum(last.v) + ' ' + unit + '</span></div>';
    }

    /* แท่งแนวนอน */
    function admBars(items?: any): any {
        var max: any = Math.max.apply(null, items.map(function(x?: any): any { return x.v; })) || 1;
        return '<div class="adm-bars">' + items.map(function(x?: any): any {
            return '<div class="adm-bar"><span class="nm">' + esc(x.name) + '</span>'
                    + '<span class="tr"><i style="width:' + ((x.v / max) * 100).toFixed(1) + '%;background:' + (x.color || '#6043B6') + '"></i></span>'
                    + '<b>' + admNum(x.v) + '</b></div>';
        }).join('') + '</div>';
    }

    /* โดนัท */
    function admDonut(items?: any, unit?: any, shortFmt?: any): any {
        unit = unit || 'เครดิต';
        var total: any = items.reduce(function(s?: any, x?: any): any { return s + x.v; }, 0) || 1;
        var r: any = 54, c: any = 2 * Math.PI * r, off: any = 0;
        var rings: any = items.map(function(x?: any): any {
            var len: any = (x.v / total) * c;
            var seg: any = '<circle cx="70" cy="70" r="' + r + '" fill="none" stroke="' + x.color + '" stroke-width="22" '
                    + 'stroke-dasharray="' + len.toFixed(2) + ' ' + (c - len).toFixed(2) + '" stroke-dashoffset="' + (-off).toFixed(2) + '"/>';
            off += len;
            return seg;
        }).join('');
        return '<div class="adm-donut"><svg viewBox="0 0 140 140" role="img" aria-label="สัดส่วนการใช้ตามกลุ่มเครื่องมือ">'
                + '<g transform="rotate(-90 70 70)">' + rings + '</g>'
                + '<text x="70" y="66" class="adm-dn-a">' + (shortFmt ? shortFmt(total) : admNum(total / 1000) + 'K') + '</text>'
                + '<text x="70" y="84" class="adm-dn-b">' + unit + '</text></svg>'
                + '<ul class="adm-legend">' + items.map(function(x?: any): any {
                    return '<li><i style="background:' + x.color + '"></i>' + esc(x.name)
                            + '<b>' + Math.round((x.v / total) * 100) + '%</b></li>';
                }).join('') + '</ul></div>';
    }


    function admPct(used?: any, quota?: any): any {
        return Math.min(999, Math.round((used / (quota || 1)) * 100));
    }

    function admMeter(used?: any, quota?: any): any {
        var p: any = admPct(used, quota);
        return '<span class="adm-meter' + (p >= 95 ? ' over' : p >= 80 ? ' warn' : '') + '">'
                + '<i style="width:' + Math.min(100, p) + '%"></i></span><b class="adm-pct">' + p + '%</b>';
    }


